1	import * as THREE from "three";
2	import { AnimationLoop } from "./AnimationLoop.js";
3	import { Scene } from "./Scene.js";
4	import { ModelLoader } from "./ModelLoader.js";
5	import { PostProcessor } from "./PostProcessor.js";
6	import { BackgroundManager } from "../manager/BackgroundManager.js";
7	import { Helpers } from "../utils/Helpers.js";
8	import type { SceneObject } from "../core/SceneObject.js";
9	import { hasWebGLRendererFeatures } from "../types/engine.types.js";
10	import type {
11	  RendererLike,
12	  RendererBackend,
13	  HasPositionSet,
14	} from "../types/engine.types.js";
15	import { hasPositionSet } from "../types/engine.types.js";
16	import type {
17	  EngineOptions,
18	  RenderBudgetOptions,
19	} from "../types/engine.types.js";
20	import type { ResponsiveSnapshot } from "../types/runtime.types.js";
21	import type {
22	  SceneFromState,
23	  CameraVars,
24	  ObjectVars,
25	} from "../types/core.types.js";
26	import { getDefaultThreeConfig } from "../config/base.config.js";
27	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
28	import {
29	  camera as cameraId,
30	  cameraTarget as cameraTargetId,
31	  THREE_LAYER_EARTH,
32	  THREE_LAYER_MARQUEE,
33	  THREE_LAYER_ROCKET,
34	} from "./setup.js";
35	
36	const DEFAULT_RENDER_BUDGET: Required<RenderBudgetOptions> = {
37	  budgetMs: 33,
38	  mode: "performance",
39	  enterSkipFrames: 2,
40	  exitSkipFrames: 8,
41	};
42	export class Engine {
43	  private _scene: Scene;
44	  private _camera: THREE.PerspectiveCamera;
45	  private _cameraTarget: THREE.Object3D;
46	  private _cameraTargetFollow: THREE.Object3D | null = null;
47	  private _cameraTargetFollowAnchorNode: THREE.Object3D | null = null;
48	  private _cameraTargetFollowLocalAnchor: THREE.Vector3 | null = null;
49	  private _followBounds = new THREE.Box3();
50	  private _followCenter = new THREE.Vector3();
51	  private _followWorldPos = new THREE.Vector3();
52	  private _renderer: RendererLike | null = null;
53	  private _postProcessor: PostProcessor | null = null;
54	  private _backgroundManager: BackgroundManager | null = null;
55	  private _rendererBackend: RendererBackend = "webgl";
56	  private _loader: ModelLoader;
57	  private _animationLoop: AnimationLoop | null = null;
58	  private _lastDelta = 0;
59	  private _contextLost = false;
60	  private _onContextLost: ((event: Event) => void) | null = null;
61	  private _onContextRestored: ((event: Event) => void) | null = null;
62	  private _opts: EngineOptions;
63	  private _pixelRatioMax: number;
64	  private _renderBudget: Required<RenderBudgetOptions>;
65	  private _renderModeState = {
66	    skipActive: false,
67	    exceededFrames: 0,
68	    stableFrames: 0,
69	  };
70	  private _didWarnPostProcessingFallback = false;
71	  private readonly _defaultThreeConfig = getDefaultThreeConfig();
72	
73	  constructor(opts: EngineOptions = {}) {
74	    this._opts = opts;
75	    this._renderBudget = this._resolveRenderBudget(opts.renderBudget);
76	    const pr = opts.pixelRatioMax;
77	    this._pixelRatioMax =
78	      typeof pr === "number" && Number.isFinite(pr) && pr > 0
79	        ? pr
80	        : this._defaultThreeConfig.pixelRatioMax;
81	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
82	    const aspect = responsive.viewportWidth / responsive.viewportHeight;
83	    const cam = opts.camera ?? {};
84	    const fov = cam.fov ?? this._defaultThreeConfig.camera.fov;
85	    const near = cam.near ?? this._defaultThreeConfig.camera.near;
86	    const far = cam.far ?? this._defaultThreeConfig.camera.far;
87	    this._camera = new THREE.PerspectiveCamera(fov, aspect, near, far);
88	    this._camera.scale.set(1, 1, 1);
89	    this._camera.layers.enable(THREE_LAYER_EARTH);
90	    this._camera.layers.enable(THREE_LAYER_MARQUEE);
91	    this._camera.layers.enable(THREE_LAYER_ROCKET);
92	    if (cam.position) {
93	      this._camera.position.set(
94	        cam.position.x ?? 0,
95	        cam.position.y ?? 0,
96	        cam.position.z ?? 0,
97	      );
98	    }
99	    this._scene = new Scene();
100	    this._cameraTarget = new THREE.Object3D();
101	    this._cameraTarget.name = cameraTargetId;
102	    const ct = opts.cameraTarget?.position;
103	    this._cameraTarget.position.set(ct?.x ?? 0, ct?.y ?? 0, ct?.z ?? 0);
104	    this._loader = new ModelLoader();
105	  }
106	
107	  init(): boolean {
108	    const targetCanvas = this._resolveTargetCanvas();
109	    if (!targetCanvas) return false;
110	
111	    const scene = this._scene.three;
112	    scene.add(this._cameraTarget);
113	
114	    this._scene.registerObject(cameraId, this._camera);
115	    this._scene.registerObject(cameraTargetId, this._cameraTarget);
116	    const cfg = this._opts.scene ?? {};
117	    scene.background =
118	      cfg.background != null ? new THREE.Color(cfg.background) : null;
119	    const fogOpt = cfg.fog;
120	    scene.fog =
121	      fogOpt != null && typeof fogOpt === "object" && "far" in fogOpt
122	        ? new THREE.Fog(
123	            fogOpt.color ?? 0x000000,
124	            fogOpt.near ?? 1000,
125	            fogOpt.far ?? 15000,
126	          )
127	        : null;
128	
129	    const rendererOpts = this._opts.renderer ?? {};
130	    this._renderer = this._createRenderer(targetCanvas, rendererOpts);
131	    if (!this._renderer) return false;
132	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
133	    const w = responsive.viewportWidth;
134	    const h = responsive.viewportHeight;
135	    this._renderer.setSize?.(w, h);
136	    this._renderer.setPixelRatio?.(Math.min(responsive.render.clampedPixelRatio, this._pixelRatioMax));
137	    if (
138	      this._renderer &&
139	      hasWebGLRendererFeatures(this._renderer) &&
140	      this._renderer.shadowMap
141	    ) {
142	      const shadowOpt = this._opts.shadowMap ?? {};
143	      this._renderer.shadowMap.enabled = shadowOpt.enabled ?? false;
144	      this._renderer.shadowMap.type = shadowOpt.type ?? THREE.PCFSoftShadowMap;
145	    }
146	    this._renderer.toneMapping = THREE.ACESFilmicToneMapping;
147	    this._renderer.toneMappingExposure = 0.56;
148	    this._renderer.outputColorSpace = THREE.SRGBColorSpace;
149	    this._attachContextEvents();
150	
151	    this._camera.aspect = w / h;
152	    this._camera.updateProjectionMatrix();
153	
154	    const postProcessorOptions = this._resolvePostProcessorOptions();
155	    this._postProcessor =
156	      this._rendererBackend === "webgl" &&
157	      this._renderer instanceof THREE.WebGLRenderer &&
158	      postProcessorOptions
159	        ? new PostProcessor(
160	            this._renderer,
161	            scene,
162	            this._camera,
163	            postProcessorOptions,
164	          )
165	        : null;
166	
167	    const loadModel = (path: string) => this._loadModel(path);
168	    const loadModelWithAnimation = (path: string) =>
169	      this._loader.loadGLTF(this._scene.three, path, {
170	        addToScene: false,
171	      });
172	    const loadTexture = (path: string) => this._loader.loadTexture(path);
173	    const loadHdrTexture = (path: string) => this._loader.loadHdrTexture(path);
174	    const compileScene = (camera?: THREE.Camera) =>
175	      this._compileScene(camera ?? this._camera);
176	    const prepareTexture = (texture: THREE.Texture) =>
177	      this._prepareTexture(texture);
178	    const getObject = (id: string) => this._scene.getObject(id);
179	    const registerObject = (
180	      id: string,
181	      object: THREE.Object3D | Record<string, unknown>,
182	    ) => this._scene.registerObject(id, object);
183	    const unregisterObject = (id: string) => this._scene.unregisterObject(id);
184	    this._scene.setContext({
185	      scene: this._scene.three,
186	      camera: this._camera,
187	      renderer: this._renderer,
188	      rendererBackend: this._rendererBackend,
189	      compileScene,
190	      prepareTexture,
191	      getObject,
192	      registerObject,
193	      unregisterObject,
194	      loadModel,
195	      loadModelWithAnimation,
196	      loadTexture,
197	      loadHdrTexture,
198	    });
199	    if (this._renderer instanceof THREE.WebGLRenderer) {
200	      this._backgroundManager = new BackgroundManager(
201	        this._renderer,
202	        this._scene.three,
203	        this._camera,
204	      );
205	      this._scene.registerObject(
206	        "env.backgroundManager.runtime",
207	        this._backgroundManager as unknown as Record<string, unknown>,
208	      );
209	    }
210	    return true;
211	  }
212	
213	  private _resolveTargetCanvas(): HTMLCanvasElement | null {
214	    const providedCanvas = this._opts.canvasElement;
215	    if (providedCanvas instanceof HTMLCanvasElement) {
216	      return providedCanvas;
217	    }
218	    const canvasId = this._opts.canvasId ?? "canvas";
219	    const el = document.getElementById(canvasId);
220	    if (!el) return null;
221	    if (el instanceof HTMLCanvasElement) {
222	      return el;
223	    }
224	    const nestedCanvas = el.querySelector("canvas");
225	    if (nestedCanvas instanceof HTMLCanvasElement) {
226	      return nestedCanvas;
227	    }
228	    return this._createCanvas(el);
229	  }
230	
231	  private _createRenderer(
232	    canvas: HTMLCanvasElement,
233	    rendererOpts: EngineOptions["renderer"] = {},
234	  ): RendererLike | null {
235	    const performance = ResponsiveRuntime.getDefault().getSnapshot().performance;
236	    const webglContext =
237	      canvas.getContext("webgl2") ??
238	      canvas.getContext("webgl") ??
239	      canvas.getContext("experimental-webgl");
240	    if (!webglContext) return null;
241	    this._rendererBackend = "webgl";
242	    try {
243	      return new THREE.WebGLRenderer({
244	        canvas,
245	        antialias: rendererOpts.antialias ?? performance.rendererAntialias,
246	        alpha: rendererOpts.alpha ?? false,
247	        powerPreference:
248	          rendererOpts.powerPreference ?? performance.rendererPowerPreference,
249	      });
250	    } catch (error) {
251	      return null;
252	    }
253	  }
254	
255	  private _createCanvas(container: HTMLElement): HTMLCanvasElement {
256	    const canvas = document.createElement("canvas");
257	    canvas.id = "canvas-webgl";
258	    container.appendChild(canvas);
259	    return canvas;
260	  }
261	
262	  private async _loadModel(path: string): Promise<THREE.Object3D> {
263	    const result = await this._loader.loadGLTF(this._scene.three, path, {
264	      addToScene: false,
265	    });
266	    if (!result.model) throw new Error(`Failed to load model: ${path}`);
267	    return result.model;
268	  }
269	
270	  runModelLoad(path: string): Promise<THREE.Object3D> {
271	    return this._loadModel(path);
272	  }
273	
274	  async setObject(id: string, object: SceneObject): Promise<void> {
275	    await this._scene.addObject(id, object);
276	  }
277	
278	  getScene(): Scene {
279	    return this._scene;
280	  }
281	
282	  setState(state: SceneFromState): void {
283	    const cam = state.camera;
284	    if (cam) {
285	      this._applyCamState(cam);
286	    }
287	    const camTarget = state.cameraTarget;
288	    if (camTarget?.position) {
289	      this.setCameraTargetPosition(
290	        this._num(camTarget.position.x),
291	        this._num(camTarget.position.y),
292	        this._num(camTarget.position.z),
293	      );
294	    }
295	    const scene = this._scene;
296	    for (const [targetId, vars] of Object.entries(state)) {
297	      if (
298	        targetId === cameraId ||
299	        targetId === cameraTargetId ||
300	        vars == null ||
301	        typeof vars !== "object"
302	      )
303	        continue;
304	      const obj = scene.getObject(targetId);
305	      if (!obj) continue;
306	      if (hasPositionSet(obj)) {
307	        this._applyVector3(obj, vars as ObjectVars);
308	        this._applyScalarProps(
309	          obj as unknown as Record<string, unknown>,
310	          vars as Record<string, unknown>,
311	        );
312	        continue;
313	      }
314	      if (!this._isPlainRecord(obj)) continue;
315	      this._applyScalarProps(obj, vars as Record<string, unknown>);
316	    }
317	  }
318	
319	  private _applyCamState(cam: CameraVars): void {
320	    this._applyVector3(this._camera, cam, false);
321	    if (cam.fov == null || !Number.isFinite(cam.fov)) return;
322	    this._camera.fov = cam.fov;
323	    this._camera.updateProjectionMatrix();
324	  }
325	
326	  private _num(v: number | undefined): number {
327	    return v != null && Number.isFinite(v) ? v : 0;
328	  }
329	
330	  private _applyVector3(
331	    obj: HasPositionSet,
332	    vars: ObjectVars | CameraVars,
333	    applyRotation = true,
334	  ): void {
335	    if (vars.position)
336	      obj.position.set(
337	        this._num(vars.position.x),
338	        this._num(vars.position.y),
339	        this._num(vars.position.z),
340	      );
341	    if (applyRotation && "rotation" in vars && vars.rotation && obj.rotation) {
342	      const r = Helpers.rotationDegToRad({
343	        x: this._num(vars.rotation.x),
344	        y: this._num(vars.rotation.y),
345	        z: this._num(vars.rotation.z),
346	      });
347	      obj.rotation.set(r.x, r.y, r.z);
348	    }
349	    if (vars.scale && obj.scale)
350	      obj.scale.set(
351	        this._num(vars.scale.x),
352	        this._num(vars.scale.y),
353	        this._num(vars.scale.z),
354	      );
355	  }
356	
357	  private _isPlainRecord(obj: unknown): obj is Record<string, unknown> {
358	    if (
359	      obj == null ||
360	      typeof obj !== "object" ||
361	      Array.isArray(obj) ||
362	      obj instanceof THREE.Object3D
363	    ) {
364	      return false;
365	    }
366	    const proto = Object.getPrototypeOf(obj);
367	    return proto === Object.prototype || proto === null;
368	  }
369	
370	  private _applyScalarProps(
371	    target: Record<string, unknown>,
372	    vars: Record<string, unknown>,
373	  ): void {
374	    for (const [key, value] of Object.entries(vars)) {
375	      if (key === "position" || key === "rotation" || key === "scale") continue;
376	      if (typeof value === "number" && Number.isFinite(value)) {
377	        target[key] = value;
378	        continue;
379	      }
380	      if (typeof value === "boolean" || typeof value === "string") {
381	        target[key] = value;
382	        continue;
383	      }
384	      if (this._isPlainRecord(value)) {
385	        const current = target[key];
386	        const nextTarget = this._isPlainRecord(current) ? current : {};
387	        target[key] = nextTarget;
388	        this._applyScalarProps(nextTarget, value);
389	      }
390	    }
391	  }
392	
393	  getCamera(): THREE.PerspectiveCamera {
394	    return this._camera;
395	  }
396	
397	  getCameraTarget(): THREE.Object3D {
398	    return this._cameraTarget;
399	  }
400	
401	  getObjectById(id: string): unknown {
402	    return this._scene.getObject(id);
403	  }
404	
405	  getObjectIds(): string[] {
406	    return this._scene.getObjectIds();
407	  }
408	
409	  getSceneObjectById(id: string): SceneObject | null {
410	    return this._scene.getSceneObject(id);
411	  }
412	
413	  removeSceneObject(id: string): void {
414	    this._scene.removeObject(id);
415	  }
416	
417	  setCameraTargetPosition(x: number, y: number, z: number): void {
418	    this._cameraTargetFollow = null;
419	    this._cameraTargetFollowAnchorNode = null;
420	    this._cameraTargetFollowLocalAnchor = null;
421	    this._cameraTarget.position.set(
422	      Number.isFinite(x) ? x : this._cameraTarget.position.x,
423	      Number.isFinite(y) ? y : this._cameraTarget.position.y,
424	      Number.isFinite(z) ? z : this._cameraTarget.position.z,
425	    );
426	  }
427	
428	  setFollowObject(object3D: THREE.Object3D): void {
429	    this._cameraTargetFollow = object3D;
430	    this._cameraTargetFollowAnchorNode = null;
431	    this._cameraTargetFollowLocalAnchor = null;
432	    const namedAnchor = object3D.getObjectByName("cameraAnchor");
433	    if (namedAnchor) {
434	      this._cameraTargetFollowAnchorNode = namedAnchor;
435	    } else {
436	      this._followBounds.setFromObject(object3D);
437	      if (!this._followBounds.isEmpty()) {
438	        this._followBounds.getCenter(this._followCenter);
439	        this._cameraTargetFollowLocalAnchor = object3D.worldToLocal(
440	          this._followCenter.clone(),
441	        );
442	      }
443	    }
444	    this._cameraTarget.position.copy(this._resolveFollowAnchor(object3D));
445	  }
446	
447	  offFollowObject(): void {
448	    this._cameraTargetFollow = null;
449	    this._cameraTargetFollowAnchorNode = null;
450	    this._cameraTargetFollowLocalAnchor = null;
451	  }
452	
453	  runBlendObject(
454	    object3D: THREE.Object3D,
455	    duration: number,
456	    animate?: (
457	      target: THREE.Vector3,
458	      destination: THREE.Vector3,
459	      duration: number,
460	    ) => void,
461	  ): void {
462	    this.offFollowObject();
463	    const anchor = this._resolveFollowAnchor(object3D);
464	    if (animate) {
465	      animate(this._cameraTarget.position, anchor, duration);
466	      return;
467	    }
468	    this._cameraTarget.position.copy(anchor);
469	  }
470	
471	  private _resolveFollowAnchor(object3D: THREE.Object3D): THREE.Vector3 {
472	    if (this._cameraTargetFollowAnchorNode) {
473	      this._cameraTargetFollowAnchorNode.getWorldPosition(this._followWorldPos);
474	      return this._followWorldPos;
475	    }
476	    if (this._cameraTargetFollowLocalAnchor) {
477	      this._followWorldPos
478	        .copy(this._cameraTargetFollowLocalAnchor)
479	        .applyMatrix4(object3D.matrixWorld);
480	      return this._followWorldPos;
481	    }
482	    this._followBounds.setFromObject(object3D);
483	    if (!this._followBounds.isEmpty()) {
484	      this._followBounds.getCenter(this._followCenter);
485	      return this._followCenter;
486	    }
487	    object3D.getWorldPosition(this._followWorldPos);
488	    return this._followWorldPos;
489	  }
490	
491	  getRenderer(): RendererLike | null {
492	    return this._renderer;
493	  }
494	
495	  getPostProcessor(): PostProcessor | null {
496	    return this._postProcessor;
497	  }
498	
499	  getBackgroundManager(): BackgroundManager | null {
500	    return this._backgroundManager;
501	  }
502	
503	  start(onUpdate: (deltaTime: number) => void, onRender: () => void): void {
504	    if (this._animationLoop) return;
505	    this._animationLoop = new AnimationLoop({
506	      budgetMs: this._renderBudget.budgetMs,
507	      onUpdate: (dt) => {
508	        this._lastDelta = dt;
509	        this._scene.update(dt);
510	        this._backgroundManager?.update(dt);
511	        onUpdate(dt);
512	      },
513	      onRender: () => {
514	        if (this._contextLost) return;
515	        if (this._cameraTargetFollow) {
516	          this._cameraTarget.position.copy(
517	            this._resolveFollowAnchor(this._cameraTargetFollow),
518	          );
519	        }
520	        this._camera.lookAt(this._cameraTarget.position);
521	        onRender();
522	        const frameExceeded = this._animationLoop?.frameExceeded ?? false;
523	        const skipPost = this._shouldSkipPostProcessing(frameExceeded);
524	        this._renderMainScene(skipPost);
525	      },
526	    });
527	    this._animationLoop.start();
528	  }
529	
530	  stop(): void {
531	    this._animationLoop?.stop();
532	    this._resetRenderModeState();
533	  }
534	
535	  setViewport(width: number, height: number): void {
536	    const dpr = Math.min(
537	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
538	      this._pixelRatioMax,
539	    );
540	    this._camera.aspect = width / height;
541	    this._camera.updateProjectionMatrix();
542	    this._renderer?.setPixelRatio?.(dpr);
543	    this._renderer?.setSize?.(width, height);
544	    this._postProcessor?.resize(width, height, dpr);
545	    this._backgroundManager?.resize(width, height, dpr);
546	  }
547	
548	  applyResponsiveSnapshot(snapshot: ResponsiveSnapshot): void {
549	    this._pixelRatioMax = snapshot.render.pixelRatioMax;
550	    this.setViewport(snapshot.viewportWidth, snapshot.viewportHeight);
551	  }
552	
553	  dispose(): void {
554	    this.stop();
555	    this._animationLoop?.dispose();
556	    this._animationLoop = null;
557	    this._postProcessor?.dispose();
558	    this._postProcessor = null;
559	    this._backgroundManager?.dispose();
560	    this._backgroundManager = null;
561	    this._loader.dispose();
562	    if (this._cameraTarget.parent)
563	      this._cameraTarget.parent.remove(this._cameraTarget);
564	    this._cameraTargetFollow = null;
565	    this._cameraTargetFollowAnchorNode = null;
566	    this._cameraTargetFollowLocalAnchor = null;
567	    this._scene.dispose();
568	    this._detachContextEvents();
569	    this._renderer?.dispose?.();
570	    this._renderer = null;
571	  }
572	
573	  private _attachContextEvents(): void {
574	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
575	    const canvas = this._renderer.domElement;
576	    this._onContextLost = (event: Event): void => {
577	      const webglEvent = event as Event & { preventDefault?: () => void };
578	      webglEvent.preventDefault?.();
579	      this._contextLost = true;
580	      this._animationLoop?.stop();
581	    };
582	    this._onContextRestored = (): void => {
583	      this._contextLost = false;
584	      this._animationLoop?.start();
585	    };
586	    canvas.addEventListener("webglcontextlost", this._onContextLost);
587	    canvas.addEventListener("webglcontextrestored", this._onContextRestored);
588	  }
589	
590	  private _detachContextEvents(): void {
591	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
592	    const canvas = this._renderer.domElement;
593	    if (this._onContextLost) {
594	      canvas.removeEventListener("webglcontextlost", this._onContextLost);
595	    }
596	    if (this._onContextRestored) {
597	      canvas.removeEventListener(
598	        "webglcontextrestored",
599	        this._onContextRestored,
600	      );
601	    }
602	    this._onContextLost = null;
603	    this._onContextRestored = null;
604	    this._contextLost = false;
605	  }
606	
607	  private _resolveRenderBudget(
608	    options: RenderBudgetOptions | undefined,
609	  ): Required<RenderBudgetOptions> {
610	    const budgetMs =
611	      Number.isFinite(options?.budgetMs as number) &&
612	      (options?.budgetMs as number) > 0
613	        ? (options?.budgetMs as number)
614	        : DEFAULT_RENDER_BUDGET.budgetMs;
615	    const mode =
616	      options?.mode === "consistent" || options?.mode === "performance"
617	        ? options.mode
618	        : DEFAULT_RENDER_BUDGET.mode;
619	    const enterSkipFrames =
620	      Number.isFinite(options?.enterSkipFrames as number) &&
621	      (options?.enterSkipFrames as number) > 0
622	        ? Math.floor(options?.enterSkipFrames as number)
623	        : DEFAULT_RENDER_BUDGET.enterSkipFrames;
624	    const exitSkipFrames =
625	      Number.isFinite(options?.exitSkipFrames as number) &&
626	      (options?.exitSkipFrames as number) > 0
627	        ? Math.floor(options?.exitSkipFrames as number)
628	        : DEFAULT_RENDER_BUDGET.exitSkipFrames;
629	    return { budgetMs, mode, enterSkipFrames, exitSkipFrames };
630	  }
631	
632	  private _resolvePostProcessorOptions(): EngineOptions["postProcessing"] | null {
633	    const options = this._opts.postProcessing;
634	    if (!options) return null;
635	    const hasBloom = options.bloom !== false && options.bloom != null;
636	    const hasVignette = options.vignette !== false && options.vignette != null;
637	    const hasFullscreenShader = options.fullscreenShader != null;
638	    if (!hasBloom && !hasVignette && !hasFullscreenShader) {
639	      return null;
640	    }
641	    return options;
642	  }
643	
644	  private _resetRenderModeState(): void {
645	    this._renderModeState.skipActive = false;
646	    this._renderModeState.exceededFrames = 0;
647	    this._renderModeState.stableFrames = 0;
648	  }
649	
650	  private _shouldSkipPostProcessing(frameExceeded: boolean): boolean {
651	    if (!this._postProcessor || this._renderBudget.mode !== "performance") {
652	      this._resetRenderModeState();
653	      return false;
654	    }
655	
656	    if (frameExceeded) {
657	      this._renderModeState.exceededFrames += 1;
658	      this._renderModeState.stableFrames = 0;
659	      if (
660	        !this._renderModeState.skipActive &&
661	        this._renderModeState.exceededFrames >=
662	          this._renderBudget.enterSkipFrames
663	      ) {
664	        this._renderModeState.skipActive = true;
665	      }
666	      return this._renderModeState.skipActive;
667	    }
668	
669	    this._renderModeState.stableFrames += 1;
670	    this._renderModeState.exceededFrames = 0;
671	    if (
672	      this._renderModeState.skipActive &&
673	      this._renderModeState.stableFrames >= this._renderBudget.exitSkipFrames
674	    ) {
675	      this._renderModeState.skipActive = false;
676	    }
677	    return this._renderModeState.skipActive;
678	  }
679	
680	  private _renderMainScene(skipPostProcessing: boolean): void {
681	    if (!this._renderer) return;
682	    this._backgroundManager?.render();
683	    if (skipPostProcessing || !this._postProcessor) {
684	      this._renderer.render?.(this._scene.three, this._camera);
685	      return;
686	    }
687	    try {
688	      this._postProcessor.render(this._scene.getBloomRoots(), this._lastDelta);
689	    } catch (error) {
690	      if (!this._didWarnPostProcessingFallback) {
691	        this._didWarnPostProcessingFallback = true;
692	      }
693	      this._renderer.render?.(this._scene.three, this._camera);
694	    }
695	  }
696	
697	  private _compileScene(camera: THREE.Camera): void {
698	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
699	    this._renderer.compile(this._scene.three, camera);
700	  }
701	
702	  private _prepareTexture(texture: THREE.Texture): void {
703	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
704	    const renderer = this._renderer as THREE.WebGLRenderer & {
705	      initTexture?: (map: THREE.Texture) => void;
706	    };
707	    renderer.initTexture?.(texture);
708	  }
709	}
