1	import * as THREE from "three";
2	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
3	import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
4	import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
5	import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
6	import { ShaderPass } from "three/addons/postprocessing/ShaderPass.js";
7	import type {
8	  PostProcessorOptions,
9	  BloomOptions,
10	  VignetteOptions,
11	  FullscreenShaderOptions,
12	} from "../types/engine.types.js";
13	import additiveBlendVertexShader from "../../shaders/post-processing/additive-blend.vertex.glsl?raw";
14	import additiveBlendFragmentShader from "../../shaders/post-processing/additive-blend.fragment.glsl?raw";
15	import { VignetteShader } from "three/addons/shaders/VignetteShader.js";
16	
17	const DEFAULT_BLOOM: Required<Omit<BloomOptions, "selective">> & {
18	  selective: boolean;
19	} = {
20	  strength: 0.12,
21	  radius: 0.35,
22	  threshold: 0.93,
23	  compositeStrength: 0.4,
24	  selective: true,
25	};
26	
27	const DEFAULT_VIGNETTE: Required<VignetteOptions> = {
28	  offset: 0.95,
29	  darkness: 1.45,
30	};
31	
32	export class PostProcessor {
33	  private _renderer: THREE.WebGLRenderer;
34	  private _scene: THREE.Scene;
35	  private _camera: THREE.Camera;
36	  private _opts: PostProcessorOptions;
37	
38	  private _composer: EffectComposer | null = null;
39	  private _bloomComposer: EffectComposer | null = null;
40	  private _finalComposer: EffectComposer | null = null;
41	  private _bloomPass: UnrealBloomPass | null = null;
42	  private _blendPass: ShaderPass | null = null;
43	  private _vignettePass: ShaderPass | null = null;
44	  private _fullscreenShaderPass: ShaderPass | null = null;
45	  private _selective = false;
46	
47	  private _darkMaterial: THREE.MeshBasicMaterial | null = null;
48	  private _materialCache = new Map<
49	    THREE.Object3D,
50	    THREE.Material | THREE.Material[]
51	  >();
52	  private _bloomDescendants = new Set<THREE.Object3D>();
53	  private _cachedBloomSignature = "";
54	  private _cachedNonBloomMeshes: THREE.Mesh[] = [];
55	  private _cachedSceneMeshes: THREE.Mesh[] = [];
56	  private _didWarnSelectiveFallback = false;
57	
58	  constructor(
59	    renderer: THREE.WebGLRenderer,
60	    scene: THREE.Scene,
61	    camera: THREE.Camera,
62	    opts: PostProcessorOptions = {},
63	  ) {
64	    this._renderer = renderer;
65	    this._scene = scene;
66	    this._camera = camera;
67	    this._opts = opts;
68	    this._setup();
69	  }
70	
71	  get isSelective(): boolean {
72	    return this._selective;
73	  }
74	
75	  private _setup(): void {
76	    const bloomOpt = this._opts.bloom;
77	    const vignetteOpt = this._opts.vignette;
78	    const fullscreenShaderOpt = this._opts.fullscreenShader;
79	    const hasBloom = bloomOpt !== false;
80	    const hasVignette = vignetteOpt !== false && vignetteOpt != null;
81	    const hasFullscreenShader = fullscreenShaderOpt != null;
82	    if (!hasBloom && !hasVignette && !hasFullscreenShader) {
83	      return;
84	    }
85	    const vignetteCfg = this._normalizeVignetteOptions(vignetteOpt);
86	    if (!hasBloom) {
87	      this._setupCustomPassPipeline(vignetteCfg, fullscreenShaderOpt ?? null);
88	      return;
89	    }
90	    const bloomCfg = this._normalizeBloomOptions(bloomOpt);
91	
92	    this._selective = bloomCfg.selective ?? true;
93	    const resolution = new THREE.Vector2(
94	      this._renderer.domElement.width,
95	      this._renderer.domElement.height,
96	    );
97	
98	    if (this._selective) {
99	      this._setupSelectiveBloom(
100	        bloomCfg,
101	        resolution,
102	        vignetteCfg,
103	        fullscreenShaderOpt ?? null,
104	      );
105	      return;
106	    }
107	    this._setupGlobalBloom(
108	      bloomCfg,
109	      resolution,
110	      vignetteCfg,
111	      fullscreenShaderOpt ?? null,
112	    );
113	  }
114	
115	  private _setupSelectiveBloom(
116	    cfg: Required<Omit<BloomOptions, "selective">> & { selective: boolean },
117	    resolution: THREE.Vector2,
118	    vignetteCfg: Required<VignetteOptions> | null,
119	    fullscreenShaderOpt: FullscreenShaderOptions | null,
120	  ): void {
121	    this._darkMaterial = new THREE.MeshBasicMaterial({ color: 0x000000 });
122	
123	    this._bloomComposer = new EffectComposer(this._renderer);
124	    this._bloomComposer.renderToScreen = false;
125	    this._bloomComposer.addPass(new RenderPass(this._scene, this._camera));
126	    this._bloomPass = new UnrealBloomPass(
127	      resolution,
128	      cfg.strength,
129	      cfg.radius,
130	      cfg.threshold,
131	    );
132	    this._bloomComposer.addPass(this._bloomPass);
133	
134	    this._finalComposer = new EffectComposer(this._renderer);
135	    this._finalComposer.addPass(new RenderPass(this._scene, this._camera));
136	
137	    const blendPass = new ShaderPass(
138	      new THREE.ShaderMaterial({
139	        uniforms: {
140	          baseTexture: { value: null },
141	          bloomTexture: {
142	            value: this._bloomComposer.renderTarget2.texture,
143	          },
144	          bloomMix: { value: cfg.compositeStrength },
145	        },
146	        vertexShader: additiveBlendVertexShader,
147	        fragmentShader: additiveBlendFragmentShader,
148	        defines: {},
149	      }),
150	      "baseTexture",
151	    );
152	    blendPass.needsSwap = true;
153	    this._blendPass = blendPass;
154	    this._finalComposer.addPass(blendPass);
155	    if (vignetteCfg) {
156	      this._vignettePass = this._createVignettePass(vignetteCfg);
157	      this._finalComposer.addPass(this._vignettePass);
158	    }
159	    this._appendFullscreenShaderPass(this._finalComposer, fullscreenShaderOpt);
160	  }
161	
162	  private _setupGlobalBloom(
163	    bloomCfg: Required<Omit<BloomOptions, "selective">> & {
164	      selective: boolean;
165	    },
166	    resolution: THREE.Vector2,
167	    vignetteCfg: Required<VignetteOptions> | null,
168	    fullscreenShaderOpt: FullscreenShaderOptions | null,
169	  ): void {
170	    this._composer = new EffectComposer(this._renderer);
171	    this._composer.addPass(new RenderPass(this._scene, this._camera));
172	    this._bloomPass = new UnrealBloomPass(
173	      resolution,
174	      bloomCfg.strength,
175	      bloomCfg.radius,
176	      bloomCfg.threshold,
177	    );
178	    this._composer.addPass(this._bloomPass);
179	    if (vignetteCfg) {
180	      this._vignettePass = this._createVignettePass(vignetteCfg);
181	      this._composer.addPass(this._vignettePass);
182	    }
183	    this._appendFullscreenShaderPass(this._composer, fullscreenShaderOpt);
184	  }
185	
186	  private _setupCustomPassPipeline(
187	    vignetteCfg: Required<VignetteOptions> | null,
188	    fullscreenShaderOpt: FullscreenShaderOptions | null,
189	  ): void {
190	    this._composer = new EffectComposer(this._renderer);
191	    this._composer.addPass(new RenderPass(this._scene, this._camera));
192	    if (vignetteCfg) {
193	      this._vignettePass = this._createVignettePass(vignetteCfg);
194	      this._composer.addPass(this._vignettePass);
195	    }
196	    this._appendFullscreenShaderPass(this._composer, fullscreenShaderOpt);
197	  }
198	
199	  private _appendFullscreenShaderPass(
200	    composer: EffectComposer,
201	    fullscreenShaderOpt: FullscreenShaderOptions | null,
202	  ): void {
203	    void composer;
204	    void fullscreenShaderOpt;
205	    return;
206	  }
207	
208	  render(bloomRoots: Set<THREE.Object3D>, deltaTime?: number): void {
209	    this._updateFullscreenShaderUniforms();
210	    if (!this._bloomPass) {
211	      if (this._composer) {
212	        this._composer.render(deltaTime);
213	        return;
214	      }
215	      this._renderer.render(this._scene, this._camera);
216	      return;
217	    }
218	
219	    if (this._selective) {
220	      const hasRoots = this._hasRenderableBloomRoots(bloomRoots);
221	      this._renderSelective(bloomRoots, hasRoots, deltaTime);
222	      return;
223	    }
224	    this._composer?.render(deltaTime);
225	  }
226	
227	  private _renderSelective(
228	    bloomRoots: Set<THREE.Object3D>,
229	    hasRoots: boolean,
230	    deltaTime?: number,
231	  ): void {
232	    if (
233	      !this._selective ||
234	      !this._bloomComposer ||
235	      !this._finalComposer ||
236	      !this._darkMaterial
237	    ) {
238	      this._composer?.render(deltaTime);
239	      return;
240	    }
241	    if (!hasRoots) {
242	      this._renderer.render(this._scene, this._camera);
243	      return;
244	    }
245	
246	    try {
247	      try {
248	        this._prepareBloomScene(hasRoots, bloomRoots);
249	        this._bloomComposer.render(deltaTime);
250	      } finally {
251	        this._restoreMaterials();
252	      }
253	      this._finalComposer.render(deltaTime);
254	    } catch (error) {
255	      if (!this._didWarnSelectiveFallback) {
256	        this._didWarnSelectiveFallback = true;
257	      }
258	      this._renderer.render(this._scene, this._camera);
259	    }
260	  }
261	
262	  private _prepareBloomScene(
263	    hasRoots: boolean,
264	    bloomRoots: Set<THREE.Object3D>,
265	  ): void {
266	    if (hasRoots) {
267	      this._darkenNonBloom(bloomRoots);
268	      return;
269	    }
270	    this._darkenAllMeshes();
271	  }
272	
273	  private _darkenNonBloom(bloomRoots: Set<THREE.Object3D>): void {
274	    const dark = this._darkMaterial!;
275	    this._materialCache.clear();
276	    const signature = this._createBloomSignature(bloomRoots);
277	    if (signature !== this._cachedBloomSignature) {
278	      this._cachedBloomSignature = signature;
279	      this._rebuildNonBloomMeshCache(bloomRoots);
280	    }
281	
282	    for (const mesh of this._cachedNonBloomMeshes) {
283	      this._materialCache.set(mesh, mesh.material);
284	      mesh.material = dark;
285	    }
286	  }
287	
288	  private _darkenAllMeshes(): void {
289	    const dark = this._darkMaterial!;
290	    this._materialCache.clear();
291	    if (this._cachedSceneMeshes.length === 0) {
292	      this._cachedSceneMeshes = this._collectSceneMeshes();
293	    }
294	    for (const mesh of this._cachedSceneMeshes) {
295	      this._materialCache.set(mesh, mesh.material);
296	      mesh.material = dark;
297	    }
298	  }
299	
300	  private _hasRenderableBloomRoots(bloomRoots: Set<THREE.Object3D>): boolean {
301	    if (bloomRoots.size === 0) return false;
302	    for (const root of bloomRoots) {
303	      if (root.parent) return true;
304	    }
305	    return false;
306	  }
307	
308	  private _normalizeBloomOptions(
309	    bloomOpt: PostProcessorOptions["bloom"],
310	  ): Required<Omit<BloomOptions, "selective">> & { selective: boolean } {
311	    if (typeof bloomOpt !== "object" || bloomOpt == null) {
312	      return { ...DEFAULT_BLOOM };
313	    }
314	    const strength = this._clampFinite(
315	      bloomOpt.strength,
316	      DEFAULT_BLOOM.strength,
317	      0,
318	      5,
319	    );
320	    const radius = this._clampFinite(
321	      bloomOpt.radius,
322	      DEFAULT_BLOOM.radius,
323	      0,
324	      2,
325	    );
326	    const threshold = this._clampFinite(
327	      bloomOpt.threshold,
328	      DEFAULT_BLOOM.threshold,
329	      0,
330	      2,
331	    );
332	    const compositeStrength = this._clampFinite(
333	      bloomOpt.compositeStrength,
334	      DEFAULT_BLOOM.compositeStrength,
335	      0,
336	      1,
337	    );
338	    const selective =
339	      typeof bloomOpt.selective === "boolean"
340	        ? bloomOpt.selective
341	        : DEFAULT_BLOOM.selective;
342	    return { strength, radius, threshold, compositeStrength, selective };
343	  }
344	
345	  private _normalizeVignetteOptions(
346	    vignetteOpt: PostProcessorOptions["vignette"],
347	  ): Required<VignetteOptions> | null {
348	    if (vignetteOpt === false || vignetteOpt == null) return null;
349	    if (vignetteOpt === true) return { ...DEFAULT_VIGNETTE };
350	    return {
351	      offset: this._clampFinite(
352	        vignetteOpt.offset,
353	        DEFAULT_VIGNETTE.offset,
354	        0,
355	        4,
356	      ),
357	      darkness: this._clampFinite(
358	        vignetteOpt.darkness,
359	        DEFAULT_VIGNETTE.darkness,
360	        0,
361	        4,
362	      ),
363	    };
364	  }
365	
366	  private _createVignettePass(
367	    vignetteCfg: Required<VignetteOptions>,
368	  ): ShaderPass {
369	    const pass = new ShaderPass(VignetteShader);
370	    pass.uniforms.offset.value = vignetteCfg.offset;
371	    pass.uniforms.darkness.value = vignetteCfg.darkness;
372	    return pass;
373	  }
374	
375	  private _updateFullscreenShaderUniforms(): void {
376	    if (!this._fullscreenShaderPass) return;
377	    const uniforms = this._fullscreenShaderPass.uniforms;
378	    if (!uniforms) return;
379	    uniforms.iTime.value = performance.now() * 0.001;
380	    uniforms.iResolution.value.set(
381	      this._renderer.domElement.width,
382	      this._renderer.domElement.height,
383	    );
384	  }
385	
386	  private _clampFinite(
387	    value: number | undefined,
388	    fallback: number,
389	    min: number,
390	    max: number,
391	  ): number {
392	    if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
393	    return Math.max(min, Math.min(max, value));
394	  }
395	
396	  private _restoreMaterials(): void {
397	    for (const [mesh, material] of this._materialCache) {
398	      (mesh as THREE.Mesh).material = material;
399	    }
400	    this._materialCache.clear();
401	  }
402	
403	  private _createBloomSignature(bloomRoots: Set<THREE.Object3D>): string {
404	    return Array.from(bloomRoots)
405	      .filter((root) => !!root.parent)
406	      .map((root) => root.uuid)
407	      .sort()
408	      .join("|");
409	  }
410	
411	  private _rebuildNonBloomMeshCache(bloomRoots: Set<THREE.Object3D>): void {
412	    this._bloomDescendants.clear();
413	    for (const root of bloomRoots) {
414	      root.traverse((child) => this._bloomDescendants.add(child));
415	    }
416	    this._cachedSceneMeshes = this._collectSceneMeshes();
417	    this._cachedNonBloomMeshes = this._cachedSceneMeshes.filter(
418	      (mesh) => !this._bloomDescendants.has(mesh),
419	    );
420	  }
421	
422	  private _collectSceneMeshes(): THREE.Mesh[] {
423	    const meshes: THREE.Mesh[] = [];
424	    this._scene.traverse((obj) => {
425	      const mesh = obj as THREE.Mesh;
426	      if (!mesh.isMesh) return;
427	      meshes.push(mesh);
428	    });
429	    return meshes;
430	  }
431	
432	  resize(width: number, height: number, pixelRatio?: number): void {
433	    const dpr =
434	      pixelRatio ??
435	      Math.min(
436	        ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
437	        2,
438	      );
439	
440	    if (this._selective) {
441	      this._bloomComposer?.setSize(width, height);
442	      this._bloomComposer?.setPixelRatio(dpr);
443	      this._finalComposer?.setSize(width, height);
444	      this._finalComposer?.setPixelRatio(dpr);
445	    } else {
446	      this._composer?.setSize(width, height);
447	      this._composer?.setPixelRatio(dpr);
448	    }
449	
450	    if (this._bloomPass) {
451	      this._bloomPass.resolution.set(width, height);
452	    }
453	    if (this._fullscreenShaderPass?.uniforms?.iResolution?.value) {
454	      this._fullscreenShaderPass.uniforms.iResolution.value.set(width, height);
455	    }
456	  }
457	
458	  getComposer(): EffectComposer | null {
459	    return this._selective ? this._finalComposer : this._composer;
460	  }
461	
462	  getBloomPass(): UnrealBloomPass | null {
463	    return this._bloomPass;
464	  }
465	
466	  getBloomOptions(): Required<Omit<BloomOptions, "selective">> | null {
467	    if (!this._bloomPass) return null;
468	    return {
469	      strength: this._bloomPass.strength,
470	      radius: this._bloomPass.radius,
471	      threshold: this._bloomPass.threshold,
472	      compositeStrength: this._readBloomCompositeStrength(),
473	    };
474	  }
475	
476	  setBloomOptions(options: BloomOptions): void {
477	    if (!this._bloomPass) return;
478	    const normalized = this._normalizeBloomOptions(options);
479	    this._bloomPass.strength = normalized.strength;
480	    this._bloomPass.radius = normalized.radius;
481	    this._bloomPass.threshold = normalized.threshold;
482	    const blendUniform = this._blendPass?.uniforms?.bloomMix;
483	    if (blendUniform) {
484	      blendUniform.value = normalized.compositeStrength;
485	    }
486	  }
487	
488	  getVignetteOptions(): Required<VignetteOptions> | null {
489	    const uniforms = this._vignettePass?.uniforms;
490	    if (!uniforms) return null;
491	    return {
492	      offset: uniforms.offset.value,
493	      darkness: uniforms.darkness.value,
494	    };
495	  }
496	
497	  setVignetteOptions(options: VignetteOptions): void {
498	    const uniforms = this._vignettePass?.uniforms;
499	    if (!uniforms) return;
500	    const normalized = this._normalizeVignetteOptions(options);
501	    if (!normalized) return;
502	    uniforms.offset.value = normalized.offset;
503	    uniforms.darkness.value = normalized.darkness;
504	  }
505	
506	  dispose(): void {
507	    this._composer?.dispose();
508	    this._composer = null;
509	    this._bloomComposer?.dispose();
510	    this._bloomComposer = null;
511	    this._finalComposer?.dispose();
512	    this._finalComposer = null;
513	    this._bloomPass?.dispose();
514	    this._bloomPass = null;
515	    this._blendPass = null;
516	    this._vignettePass = null;
517	    const fullscreenMaterial = this._fullscreenShaderPass
518	      ?.material as THREE.ShaderMaterial | undefined;
519	    fullscreenMaterial?.dispose();
520	    this._fullscreenShaderPass = null;
521	    this._darkMaterial?.dispose();
522	    this._darkMaterial = null;
523	    this._materialCache.clear();
524	    this._bloomDescendants.clear();
525	    this._cachedBloomSignature = "";
526	    this._cachedNonBloomMeshes = [];
527	    this._cachedSceneMeshes = [];
528	    this._didWarnSelectiveFallback = false;
529	  }
530	
531	  private _readBloomCompositeStrength(): number {
532	    const uniform = this._blendPass?.uniforms?.bloomMix;
533	    if (!uniform || typeof uniform.value !== "number") {
534	      return DEFAULT_BLOOM.compositeStrength;
535	    }
536	    return uniform.value;
537	  }
538	}
