152	  private _applyMeshShadowSettings(group: THREE.Group): void {
153	    const cast = this._options.meshShadow?.cast;
154	    const receive = this._options.meshShadow?.receive;
155	    group.traverse((obj) => {
156	      if (!(obj instanceof THREE.Mesh)) return;
157	      obj.castShadow = cast ?? false;
158	      obj.receiveShadow = receive ?? false;
159	    });
160	  }
