275	  private _applyGroundShader(group: THREE.Group): void {
276	    this._shaderMaterials = [];
277	    if (!this._isShaderEnabled()) return;
278	    if (!this._shaderNoiseTexture || !this._shaderNearestNoiseTexture || !this._mouseTexture) {
279	      return;
280	    }
281	    const replacedMaterials = new Set<THREE.Material>();
282	    group.traverse((child) => {
283	      if (!(child instanceof THREE.Mesh)) return;
284	      const materials = Array.isArray(child.material)
285	        ? child.material
286	        : [child.material];
287	      for (const material of materials) replacedMaterials.add(material);
288	      child.material = this._createShaderMaterialSet(child.material);
289	    });
290	    for (const material of replacedMaterials) material.dispose();
291	  }
292	
293	  private _createShaderMaterialSet(
294	    material: THREE.Material | THREE.Material[],
295	  ): THREE.Material | THREE.Material[] {
296	    if (Array.isArray(material)) {
297	      return material.map((entry) => this._createShaderMaterial(entry));
298	    }
299	    return this._createShaderMaterial(material);
300	  }
301	
302	  private _createShaderMaterial(material: THREE.Material): THREE.Material {
303	    const nextMaterial = new THREE.ShaderMaterial({
304	      uniforms: {
305	        uGroundResolution: { value: this._resolution.clone() },
306	        uGroundTime: { value: this._elapsedTime },
307	        uGroundPage: { value: this._readShaderRuntimeValue("page") },
308	        uGroundScrollProgress: {
309	          value: this._readShaderRuntimeValue("scrollProgress"),
310	        },
311	        uGroundTransition: {
312	          value: this._readShaderRuntimeValue("transition"),
313	        },
314	        uGroundTransitionDirection: {
315	          value: this._readShaderRuntimeValue("transitionDirection"),
316	        },
317	        uGroundChapter: {
318	          value: this._readShaderRuntimeValue("chapter"),
319	        },
320	        uGroundTransitionColor: {
321	          value: this._transitionColor.clone(),
322	        },
323	        uGroundLightColor: {
324	          value: this._lightColor.clone(),
325	        },
326	        uGroundDarkColor: {
327	          value: this._darkColor.clone(),
328	        },
329	        tGroundNoise: { value: this._shaderNoiseTexture },
330	        tGroundNearestNoise: {
331	          value: this._shaderNearestNoiseTexture,
332	        },
333	        tGroundMouse: { value: this._mouseTexture },
334	      },
335	      vertexShader: groundSurfaceVertexShader,
336	      fragmentShader: groundSurfaceFragmentShader,
337	      transparent: false,
338	      depthTest: true,
339	      depthWrite: true,
340	      side: material.side,
341	    });
342	    this._shaderMaterials.push(nextMaterial);
343	    return nextMaterial;
344	  }
345	
346	  private _syncShaderUniforms(): void {
347	    if (this._shaderMaterials.length === 0) return;
348	    this._updateResolution();
349	    this._resolveShaderColors();
350	    const page = this._readShaderRuntimeValue("page");
351	    const scrollProgress = this._readShaderRuntimeValue("scrollProgress");
352	    const transition = this._readShaderRuntimeValue("transition");
353	    const transitionDirection = this._readShaderRuntimeValue(
354	      "transitionDirection",
355	    );
356	    const chapter = this._readShaderRuntimeValue("chapter");
357	    for (const material of this._shaderMaterials) {
358	      material.uniforms.uGroundResolution.value.copy(this._resolution);
359	      material.uniforms.uGroundTime.value = this._elapsedTime;
360	      material.uniforms.uGroundPage.value = page;
361	      material.uniforms.uGroundScrollProgress.value = scrollProgress;
362	      material.uniforms.uGroundTransition.value = transition;
363	      material.uniforms.uGroundTransitionDirection.value = transitionDirection;
364	      material.uniforms.uGroundChapter.value = chapter;
365	      material.uniforms.uGroundTransitionColor.value.copy(
366	        this._transitionColor,
367	      );
368	      material.uniforms.uGroundLightColor.value.copy(this._lightColor);
369	      material.uniforms.uGroundDarkColor.value.copy(this._darkColor);
370	      material.uniforms.tGroundNoise.value = this._shaderNoiseTexture;
371	      material.uniforms.tGroundNearestNoise.value = this._shaderNearestNoiseTexture;
372	      material.uniforms.tGroundMouse.value = this._mouseTexture;
373	    }
374	  }
375	
376	  private _readShaderRuntimeValue(
377	    key: "page" | "scrollProgress" | "transition" | "transitionDirection" | "chapter",
378	  ): number {
379	    const runtimeValue = this._runtimeState[key];
380	    if (typeof runtimeValue === "number" && Number.isFinite(runtimeValue)) {
381	      return runtimeValue;
382	    }
383	    const runtime = this._options.shader?.runtime;
384	    const fallback = GROUND_SHADER_DEFAULTS.runtime[key];
385	    const value = runtime?.[key];
386	    if (typeof value === "number" && Number.isFinite(value)) return value;
387	    return fallback;
388	  }
389	
390	  private _resolveMouseTextureSize(): number {
391	    const raw = this._options.shader?.mouseTextureSize;
392	    if (!Number.isFinite(raw)) return GROUND_SHADER_DEFAULTS.mouseTextureSize;
393	    return Math.max(8, Math.round(raw as number));
394	  }
395	
396	  private _resolveShaderColors(): void {
397	    const colors = this._options.shader?.colors;
398	    this._transitionColor.setHex(
399	      colors?.transition ?? GROUND_SHADER_DEFAULTS.colors.transition,
400	    );
401	    this._lightColor.setHex(colors?.light ?? GROUND_SHADER_DEFAULTS.colors.light);
402	    this._darkColor.setHex(colors?.dark ?? GROUND_SHADER_DEFAULTS.colors.dark);
403	  }
404	
405	  private _updateResolution(): void {
406	    if (typeof window === "undefined") {
407	      this._resolution.set(
408	        GROUND_DEFAULT_RESOLUTION,
409	        GROUND_DEFAULT_RESOLUTION,
410	      );
411	      return;
412	    }
413	      this._resolution.set(
414	      Math.max(
415	        GROUND_DEFAULT_RESOLUTION,
416	        ResponsiveRuntime.getDefault().getSnapshot().viewportWidth,
417	      ),
418	      Math.max(
419	        GROUND_DEFAULT_RESOLUTION,
420	        ResponsiveRuntime.getDefault().getSnapshot().viewportHeight,
421	      ),
422	      );
423	    }
424	
425	  private _updateMouseTexture(): void {
426	    const mouseTexture = this._mouseTexture;
427	    const mouseTextureData = this._mouseTextureData;
428	    if (!mouseTexture || !mouseTextureData) return;
429	    for (
430	      let index = 0;
431	      index < mouseTextureData.length;
432	      index += GROUND_MOUSE_TEXTURE_CHANNELS
433	    ) {
434	      mouseTextureData[index] *= GROUND_MOUSE_TEXTURE_FADE;
435	      mouseTextureData[index + 1] *= GROUND_MOUSE_TEXTURE_FADE;
436	      mouseTextureData[index + 2] *= GROUND_MOUSE_TEXTURE_FADE;
437	      mouseTextureData[index + 3] = 1;
438	    }
439	    if (!this._pointerActive) {
440	      mouseTexture.needsUpdate = true;
441	      return;
442	    }
443	
444	    const size = this._mouseTextureSize;
445	    const pointerX = this._pointerUv.x * (size - 1);
446	    const pointerY = this._pointerUv.y * (size - 1);
447	    const radius = Math.max(1, Math.round(size * GROUND_MOUSE_TEXTURE_RADIUS));
448	
449	    for (let y = -radius; y <= radius; y += 1) {
450	      const pixelY = Math.round(pointerY + y);
451	      if (pixelY < 0 || pixelY >= size) continue;
452	      for (let x = -radius; x <= radius; x += 1) {
453	        const pixelX = Math.round(pointerX + x);
454	        if (pixelX < 0 || pixelX >= size) continue;
455	        const distance = Math.sqrt(x * x + y * y) / radius;
456	        if (distance > 1) continue;
457	        const strength = Math.pow(1 - distance, GROUND_MOUSE_TEXTURE_FALLOFF);
458	        const pixelIndex =
459	          (pixelY * size + pixelX) * GROUND_MOUSE_TEXTURE_CHANNELS;
460	        mouseTextureData[pixelIndex] = Math.max(
461	          mouseTextureData[pixelIndex],
462	          strength,
463	        );
464	        mouseTextureData[pixelIndex + 1] = Math.max(
465	          mouseTextureData[pixelIndex + 1],
466	          strength * 0.6,
467	        );
468	        mouseTextureData[pixelIndex + 2] = Math.max(
469	          mouseTextureData[pixelIndex + 2],
470	          strength * 0.85,
471	        );
472	      }
473	    }
474	
475	    mouseTexture.needsUpdate = true;
476	  }
477	
478	  private _installPointerListeners(): void {
479	    if (this._pointerListenersAttached || typeof window === "undefined") return;
480	    window.addEventListener("pointermove", this._onPointerMove, { passive: true });
481	    window.addEventListener("pointerleave", this._onPointerLeave);
482	    this._pointerListenersAttached = true;
483	  }
484	
485	  private _removePointerListeners(): void {
486	    if (!this._pointerListenersAttached || typeof window === "undefined") return;
487	    window.removeEventListener("pointermove", this._onPointerMove);
488	    window.removeEventListener("pointerleave", this._onPointerLeave);
489	    this._pointerListenersAttached = false;
490	  }
491	
492	  private _disposeShaderResources(): void {
493	    this._shaderMaterials = [];
494	    this._shaderNoiseTexture?.dispose();
495	    this._shaderNearestNoiseTexture?.dispose();
496	    this._mouseTexture?.dispose();
497	    this._shaderNoiseTexture = null;
498	    this._shaderNearestNoiseTexture = null;
499	    this._mouseTexture = null;
500	    this._mouseTextureData = null;
501	    this._mouseTextureSize = GROUND_SHADER_DEFAULTS.mouseTextureSize;
502	  }
503	
504	  private _isShaderEnabled(): boolean {
505	    return this._options.shader?.enabled ?? GROUND_SHADER_DEFAULTS.enabled;
506	  }
507	
508	  private _disposeGroup(group: THREE.Group | null): void {
509	    if (!group) return;
510	    group.traverse((child) => {
511	      if (!(child as THREE.Mesh).isMesh) return;
512	      const mesh = child as THREE.Mesh;
513	      mesh.geometry?.dispose();
514	      const materials = Array.isArray(mesh.material)
515	        ? mesh.material
516	        : [mesh.material];
517	      for (const material of materials) {
518	        material?.dispose?.();
519	      }
520	    });
521	  }
522	}
