250	      ? await this._context.loadTexture(url)
251	      : await new Promise<THREE.Texture>((resolve, reject) => {
252	          new THREE.TextureLoader().load(url, resolve, undefined, reject);
253	        });
254	    if (sRgb) texture.colorSpace = THREE.SRGBColorSpace;
255	    return texture;
256	  }
257	
258	  private _prepareTextures(textures: THREE.Texture[]): void {
259	    const prepareTexture = this._context?.prepareTexture;
260	    if (!prepareTexture) return;
261	    textures.forEach((texture) => prepareTexture(texture));
262	  }
263	
264	  private _prewarmSceneCompile(root: THREE.Object3D): void {
265	    if (this._didPrewarm) return;
266	    const compileScene = this._context?.compileScene;
267	    if (!compileScene) return;
268	    const previousVisible = root.visible;
269	    root.visible = true;
270	    compileScene();
271	    root.visible = previousVisible;
272	    this._didPrewarm = true;
273	  }
274	}
