172	            shader?.chapter,
173	            this._finiteOr(this._options.chapter, 0),
174	          ),
175	        },
176	        uTransition: {
177	          value: this._finiteOr(
178	            shader?.transition,
179	            this._finiteOr(this._options.transition, 0),
180	          ),
181	        },
182	        uOpacity: { value: this._finiteOr(shader?.opacity, 0.16) },
183	        uRocketInfluence: { value: 0 },
