230	  private _applyStaticUniforms(): void {
231	    const uniforms = this._material?.uniforms as
232	      | ShaderUniformRecord
233	      | undefined;
234	    if (!uniforms) return;
235	    this._setUniformNumber(
236	      uniforms,
237	      "uChapter",
238	      this._finiteOr(
239	        this._options.chapter,
240	        this._finiteOr(this._options.shader?.chapter, 0),
241	      ),
242	    );
243	    this._setUniformNumber(
244	      uniforms,
245	      "uTransition",
246	      this._finiteOr(
