253	  private _applyDynamicUniforms(): void {
254	    const uniforms = this._material?.uniforms as
255	      | ShaderUniformRecord
256	      | undefined;
257	    if (!uniforms) return;
258	    this._setUniformNumber(uniforms, "uTime", this._elapsedTime);
259	    this._applyResolutionUniform(uniforms);
260	    this._applyRocketUniforms(uniforms);
