263	  private _applyResolutionUniform(uniforms: ShaderUniformRecord): void {
264	    const target = uniforms.uResolution;
265	    if (!target) return;
266	    const renderer = this._context?.renderer;
267	    const width = renderer?.domElement?.width;
268	    const height = renderer?.domElement?.height;
269	    if (
270	      !(target.value instanceof THREE.Vector2) ||
271	      !Number.isFinite(width) ||
272	      !Number.isFinite(height)
273	    ) {
274	      return;
275	    }
276	    target.value.set(width as number, height as number);
277	  }
278	
279	  private _applyRocketUniforms(uniforms: ShaderUniformRecord): void {
280	    const root = this.getTimelineRoot();
281	    const rocketObject = this._context?.getObject(rocket) as
282	      | THREE.Object3D
283	      | null;
284	    const rocketInfluence = uniforms.uRocketInfluence;
285	    const rocketUv = uniforms.uRocketUv;
286	    if (!root || !rocketObject || !rocketInfluence || !rocketUv) {
287	      if (rocketInfluence) rocketInfluence.value = 0;
288	      return;
289	    }
290	
291	    rocketObject.getWorldPosition(this._rocketWorldPosition);
292	    this._rocketLocalPosition.copy(this._rocketWorldPosition);
293	    root.worldToLocal(this._rocketLocalPosition);
294	
295	    const plane = this._resolvePlaneOptions();
296	    const halfWidth = plane.width * 0.5;
297	    const halfHeight = plane.height * 0.5;
298	    const normalizedX = this._rocketLocalPosition.x / Math.max(halfWidth, 0.0001);
299	    const normalizedY = this._rocketLocalPosition.y / Math.max(halfHeight, 0.0001);
300	    const lateralDistance = Math.max(Math.abs(normalizedX), Math.abs(normalizedY));
301	    const depthDistance = Math.abs(this._rocketLocalPosition.z);
302	    const lateralInfluence = 1 - this._smoothstep(0.35, 1.2, lateralDistance);
303	    const depthInfluence =
304	      1 -
305	      this._smoothstep(
306	        CLOUD_ROCKET_EFFECT_DEPTH * 0.2,
307	        CLOUD_ROCKET_EFFECT_DEPTH,
308	        depthDistance,
309	      );
310	    rocketInfluence.value = lateralInfluence * depthInfluence;
311	    const rocketUvValue =
312	      rocketUv.value instanceof THREE.Vector2
313	        ? rocketUv.value
314	        : new THREE.Vector2();
315	    rocketUvValue.set(normalizedX * 0.5 + 0.5, normalizedY * 0.5 + 0.5);
316	    rocketUv.value = rocketUvValue;
317	  }
318	
319	  private _createCurvedPlaneGeometry(): THREE.PlaneGeometry {
320	    const plane = this._resolvePlaneOptions();
321	    const geometry = new THREE.PlaneGeometry(
322	      plane.width,
323	      plane.height,
324	      plane.segments,
325	      plane.segments,
326	    );
327	    if (plane.curveDepth <= 0 || plane.segments <= 1) {
328	      geometry.computeVertexNormals();
329	      geometry.computeBoundingSphere();
330	      return geometry;
331	    }
332	    const position = geometry.getAttribute("position");
333	    for (let index = 0; index < position.count; index += 1) {
334	      const x = position.getX(index);
335	      const y = position.getY(index);
336	      const normalizedX = Math.abs(x / (plane.width * 0.5));
337	      const normalizedY = Math.abs(y / (plane.height * 0.5));
338	      const clampedX = THREE.MathUtils.clamp(normalizedX, 0, 1);
339	      const clampedY = THREE.MathUtils.clamp(normalizedY, 0, 1);
340	      const edgeCurve = this._smoothstep(
341	        0.72,
342	        1,
343	        Math.pow(clampedX, plane.curvePower),
344	      );
345	      const horizontalCurve =
346	        (1 - Math.cos(edgeCurve * Math.PI * 0.5)) * edgeCurve;
347	      const verticalCurve = 1 - Math.pow(clampedY, 1.5) * 0.03;
348	      position.setZ(
349	        index,
350	        plane.curveDepth *
351	          horizontalCurve *
352	          THREE.MathUtils.clamp(verticalCurve, 0.96, 1),
353	      );
354	    }
355	    position.needsUpdate = true;
356	    geometry.computeVertexNormals();
357	    geometry.computeBoundingSphere();
358	    return geometry;
359	  }
360	
361	  private _resolvePlaneOptions(): Required<
362	    NonNullable<CloudPlaneObjectOptions["plane"]>
363	  > {
364	    const plane = this._options.plane;
365	    const fallbackSize = this._resolvePositiveNumber(
366	      plane?.size,
367	      CLOUD_PLANE_WIDTH,
368	    );
369	    return {
370	      size: fallbackSize,
371	      width: this._resolvePositiveNumber(plane?.width, fallbackSize),
372	      height: this._resolvePositiveNumber(plane?.height, CLOUD_PLANE_HEIGHT),
373	      segments: Math.max(
374	        1,
375	        Math.round(
376	          this._resolvePositiveNumber(plane?.segments, CLOUD_PLANE_SEGMENTS),
377	        ),
378	      ),
379	      curveDepth: this._resolvePositiveNumber(
380	        plane?.curveDepth,
381	        CLOUD_PLANE_CURVE_DEPTH,
382	      ),
383	      curvePower: this._resolvePositiveNumber(
384	        plane?.curvePower,
385	        CLOUD_PLANE_CURVE_POWER,
386	      ),
387	    };
388	  }
389	
390	  private _smoothstep(edge0: number, edge1: number, value: number): number {
391	    const normalized = THREE.MathUtils.clamp(
392	      (value - edge0) / Math.max(edge1 - edge0, Number.EPSILON),
393	      0,
394	      1,
395	    );
396	    return normalized * normalized * (3 - 2 * normalized);
397	  }
398	
399	  private _clearRuntime(): void {
400	    if (this._mesh) {
401	      this._mesh.geometry.dispose();
402	      this._mesh.material.dispose();
403	      this._mesh.parent?.remove(this._mesh);
404	    }
405	    this._mesh = null;
406	    this._material = null;
407	    this._disposeTextures();
408	    this._elapsedTime = 0;
409	  }
410	
411	  private _disposeTextures(): void {
412	    for (const key of this._sharedTextureKeys) {
413	      const cached = CloudPlane._sharedTextures.get(key);
414	      if (!cached) continue;
415	      cached.refs -= 1;
416	      if (cached.refs <= 0) {
417	        cached.texture.dispose();
418	        CloudPlane._sharedTextures.delete(key);
419	      }
420	    }
421	    this._sharedTextureKeys.clear();
422	    this._mouseTexture?.dispose();
423	    this._perlinTexture = null;
424	    this._noiseTexture = null;
425	    this._mouseTexture = null;
426	    this._mouseTextureData = null;
427	  }
428	
429	  private async _loadSharedTexture(
430	    url: string,
431	    prepare: (texture: THREE.Texture) => THREE.Texture,
432	  ): Promise<THREE.Texture> {
433	    const cached = CloudPlane._sharedTextures.get(url);
434	    if (cached) {
435	      cached.refs += 1;
436	      this._sharedTextureKeys.add(url);
437	      return cached.texture;
438	    }
439	    const loader = this._context?.loadTexture;
440	    if (!loader) {
441	      throw new Error(`Cloud texture loader is unavailable for ${url}`);
442	    }
443	    const texture = prepare.call(this, await loader(url));
444	    CloudPlane._sharedTextures.set(url, {
445	      texture,
446	      refs: 1,
447	    });
448	    this._sharedTextureKeys.add(url);
449	    return texture;
450	  }
451	
452	  private _getLayerLabel(): string {
453	    const label = this._options.label?.trim();
454	    return label && label.length > 0 ? label : "cloudPlaneRoot";
455	  }
456	
457	  private _createMouseTexture(): void {
458	    this._mouseTextureData = new Float32Array(
459	      CLOUD_MOUSE_TEXTURE_SIZE *
460	        CLOUD_MOUSE_TEXTURE_SIZE *
461	        CLOUD_MOUSE_TEXTURE_CHANNELS,
462	    );
463	    this._mouseTexture = new THREE.DataTexture(
464	      this._mouseTextureData,
465	      CLOUD_MOUSE_TEXTURE_SIZE,
466	      CLOUD_MOUSE_TEXTURE_SIZE,
467	      THREE.RGBAFormat,
468	      THREE.FloatType,
469	    );
470	    this._mouseTexture.wrapS = THREE.ClampToEdgeWrapping;
471	    this._mouseTexture.wrapT = THREE.ClampToEdgeWrapping;
472	    this._mouseTexture.magFilter = THREE.LinearFilter;
473	    this._mouseTexture.minFilter = THREE.LinearFilter;
474	    this._mouseTexture.generateMipmaps = false;
475	    this._mouseTexture.needsUpdate = true;
476	  }
477	
478	  private _updateMouseTexture(): void {
479	    const mouseTexture = this._mouseTexture;
480	    const mouseTextureData = this._mouseTextureData;
481	    if (!mouseTexture || !mouseTextureData) return;
482	    for (
483	      let index = 0;
484	      index < mouseTextureData.length;
485	      index += CLOUD_MOUSE_TEXTURE_CHANNELS
486	    ) {
487	      mouseTextureData[index] *= CLOUD_MOUSE_TEXTURE_FADE;
488	      mouseTextureData[index + 1] *= CLOUD_MOUSE_TEXTURE_FADE;
489	      mouseTextureData[index + 2] *= CLOUD_MOUSE_TEXTURE_FADE;
490	      mouseTextureData[index + 3] = 1;
491	    }
492	    mouseTexture.needsUpdate = true;
493	  }
494	
495	  private _setUniformNumber(
496	    uniforms: ShaderUniformRecord,
497	    key: string,
498	    value: number,
499	  ): void {
500	    const target = uniforms[key];
501	    if (!target) return;
502	    target.value = value;
503	  }
504	
505	  private _finiteOr(value: unknown, fallback: number): number {
506	    return Number.isFinite(value as number) ? (value as number) : fallback;
507	  }
508	
509	  private _resolvePositiveNumber(value: unknown, fallback: number): number {
510	    if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
511	      return fallback;
512	    }
513	    return value;
514	  }
515	}
