341	  private _sampleProfile(
342	    progress: number,
343	  ): [SceneLightProfileStop, SceneLightProfileStop, number] | null {
344	    const stops = this._profileStops;
345	    if (stops.length === 0) return null;
346	    if (stops.length === 1) return [stops[0], stops[0], 0];
347	
348	    const p = Math.max(0, Math.min(1, progress));
349	    if (p <= stops[0].progress) return [stops[0], stops[0], 0];
350	    const last = stops[stops.length - 1];
351	    if (p >= last.progress) return [last, last, 0];
352	
353	    for (let i = 0; i < stops.length - 1; i += 1) {
354	      const left = stops[i];
355	      const right = stops[i + 1];
356	      if (p < left.progress || p > right.progress) continue;
357	      const span = Math.max(1e-6, right.progress - left.progress);
358	      return [left, right, (p - left.progress) / span];
359	    }
360	
361	    return [last, last, 0];
362	  }
