364	  private _buildFollowCameraEntries(): void {
365	    this._followCameraEntries = [];
366	    const camera = this._context?.camera;
367	    if (!(camera instanceof THREE.Object3D)) return;
368	
369	    const camPos = new THREE.Vector3();
370	    const camQuat = new THREE.Quaternion();
371	    const camInvQuat = new THREE.Quaternion();
372	    camera.getWorldPosition(camPos);
373	    camera.getWorldQuaternion(camQuat);
374	    camInvQuat.copy(camQuat).invert();
375	
376	    for (const spec of this._specs) {
377	      const rawFollow = spec.followCamera;
378	      const followOpts =
379	        typeof rawFollow === "object" && rawFollow != null ? rawFollow : null;
380	      const enabled = rawFollow === true || followOpts?.enabled === true;
381	      if (!enabled) continue;
382	
383	      const light = this._lights.get(spec.id);
384	      if (!light) continue;
385	      const rotateWithCamera = followOpts?.rotateWithCamera ?? true;
386	      const lightType = (spec.type ?? "directional").toLowerCase();
387	      const hasTarget = lightType === "directional" || lightType === "spot";
388	      const targetObj =
389	        hasTarget && light instanceof THREE.DirectionalLight
390	          ? light.target
391	          : null;
392	
393	      const positionOffset = followOpts?.positionOffset
394	        ? new THREE.Vector3(
395	            followOpts.positionOffset.x ?? 0,
396	            followOpts.positionOffset.y ?? 0,
397	            followOpts.positionOffset.z ?? 0,
398	          )
399	        : this._worldDeltaToOffset(
400	            light.position.clone().sub(camPos),
401	            rotateWithCamera,
402	            camInvQuat,
403	          );
404	
405	      const targetOffset =
406	        targetObj != null
407	          ? followOpts?.targetOffset
408	            ? new THREE.Vector3(
409	                followOpts.targetOffset.x ?? 0,
410	                followOpts.targetOffset.y ?? 0,
411	                followOpts.targetOffset.z ?? 0,
412	              )
413	            : this._worldDeltaToOffset(
414	                targetObj.position.clone().sub(camPos),
415	                rotateWithCamera,
416	                camInvQuat,
417	              )
418	          : null;
419	
420	      this._followCameraEntries.push({
421	        lightId: spec.id,
422	        rotateWithCamera,
423	        positionOffset,
424	        targetOffset,
425	      });
426	    }
427	  }
428	
429	  private _worldDeltaToOffset(
430	    delta: THREE.Vector3,
431	    rotateWithCamera: boolean,
432	    camInvQuat: THREE.Quaternion,
433	  ): THREE.Vector3 {
434	    if (!rotateWithCamera) return delta;
435	    return delta.applyQuaternion(camInvQuat);
436	  }
437	
438	  private _applyCameraFollow(): void {
439	    if (this._followCameraEntries.length === 0) return;
440	    const camera = this._context?.camera;
441	    if (!(camera instanceof THREE.Object3D)) return;
442	
443	    const camPos = this._followCamPos;
444	    const camQuat = this._followCamQuat;
445	    const worldOffset = this._followWorldOffset;
446	    camera.getWorldPosition(camPos);
447	    camera.getWorldQuaternion(camQuat);
448	
449	    for (const entry of this._followCameraEntries) {
450	      const light = this._lights.get(entry.lightId);
451	      if (!light) continue;
452	
453	      if (entry.positionOffset) {
454	        worldOffset.copy(entry.positionOffset);
455	        if (entry.rotateWithCamera) worldOffset.applyQuaternion(camQuat);
456	        light.position.copy(camPos).add(worldOffset);
457	      }
458	
459	      if (
460	        entry.targetOffset &&
461	        light instanceof THREE.DirectionalLight &&
462	        light.target
463	      ) {
464	        worldOffset.copy(entry.targetOffset);
465	        if (entry.rotateWithCamera) worldOffset.applyQuaternion(camQuat);
466	        light.target.position.copy(camPos).add(worldOffset);
467	      }
468	    }
469	  }
