37	  override async runObject(): Promise<void> {
38	    const ctx = this._context;
39	    if (!ctx) return;
40	
41	    const o = this._options;
42	    const modelUrl = o.modelUrl;
43	    if (!modelUrl) return;
44	
45	    const root = this.ensureTimelineRoot("astronautRoot");
46	    if (root) {
47	      Helpers.applyTransform(root, o);
48	    }
49	
50	    const path = this.resolveAssetPath(modelUrl);
51	    try {
52	      const gltfResult = ctx.loadModelWithAnimation
53	        ? await ctx.loadModelWithAnimation(path)
54	        : { model: await ctx.loadModel(path), mixers: [] };
55	      const group = gltfResult.model as THREE.Group | null;
56	      if (!group) return;
57	      group.traverse((child) => {
58	        if (!(child instanceof THREE.Mesh)) return;
59	        child.castShadow = true;
60	        child.receiveShadow = true;
61	      });
62	      this._model = group;
63	      this._mixers = gltfResult.mixers ?? [];
64	      this.attachToTimelineRoot(group, "astronautRoot");
65	      this._buildAttachments(group);
66	      this._applyOptionVisibility();
67	    } catch (error) {
68	    }
69	  }
70	
71	  override runUpdate(delta: number): void {
72	    if (this._mixers.length === 0) return;
73	    for (const mixer of this._mixers) {
74	      mixer.update(delta);
75	    }
76	  }
77	
78	  override dispose(): void {
79	    this._disposeAttachments();
80	    this._mixers.forEach((mixer) => {
81	      mixer.stopAllAction();
82	      if (this._model) mixer.uncacheRoot(this._model);
83	    });
84	    this._mixers = [];
85	    if (this._model) {
86	      this._model.traverse((child) => {
87	        if (!(child as THREE.Mesh).isMesh) return;
88	        const mesh = child as THREE.Mesh;
89	        mesh.geometry?.dispose();
90	        const mats = Array.isArray(mesh.material)
91	          ? mesh.material
92	          : [mesh.material];
93	        for (const m of mats) (m as THREE.Material)?.dispose?.();
94	      });
95	    }
96	    this._model = null;
97	    super.dispose();
98	  }
99	
100	  private _buildAttachments(group: THREE.Group): void {
101	    this._disposeAttachments();
102	    const attachments = Array.isArray(this._options.attachments)
103	      ? this._options.attachments
104	      : [];
105	    const registerObject = this._context?.registerObject;
106	    if (typeof registerObject !== "function") return;
107	
108	    for (const attachment of attachments) {
109	      if (!attachment?.id) continue;
110	      const anchor = new THREE.Object3D();
111	      anchor.name = attachment.id;
112	      anchor.position.set(
113	        attachment.position?.x ?? 0,
114	        attachment.position?.y ?? 0,
115	        attachment.position?.z ?? 0,
116	      );
117	      group.add(anchor);
118	      this._attachments.set(attachment.id, anchor);
119	      registerObject(attachment.id, anchor);
120	    }
121	  }
122	
123	  private _disposeAttachments(): void {
124	    const unregisterObject = this._context?.unregisterObject;
125	    for (const [id, anchor] of this._attachments.entries()) {
126	      if (anchor.parent) anchor.parent.remove(anchor);
127	      if (typeof unregisterObject === "function") {
128	        unregisterObject(id);
129	      }
130	    }
131	    this._attachments.clear();
132	  }
133	}
