430	  private _applyUniforms(
431	    material: THREE.ShaderMaterial,
432	    entry: BackgroundManagerEntry,
433	    variant: BackgroundVariantKey,
434	  ): void {
435	    const uniforms = material.uniforms as BackgroundUniformRecord;
436	    const performance = this._getPerformanceProfile();
437	    const look = this._resolveLook(entry, variant);
438	    (uniforms.uTime.value as number) = Math.max(
439	      0,
440	      this._elapsedTime - entry.shaderTimeOffset,
441	    );
