446	    (uniforms.uPointerActive.value as number) = 0;
447	    (uniforms.uTopColor.value as THREE.Color).setHex(look.topColor);
448	    (uniforms.uBottomColor.value as THREE.Color).setHex(look.bottomColor);
449	    (uniforms.uAccentColor.value as THREE.Color).setHex(look.accentColor);
