458	      BACKGROUND_STAR_DENSITY_MAX,
459	    );
460	    (uniforms.uNebulaStrength.value as number) = this._clamp(
461	      look.nebulaStrength,
462	      BACKGROUND_NEBULA_STRENGTH_MIN,
463	      BACKGROUND_NEBULA_STRENGTH_MAX,
464	    );
465	    (uniforms.uMotionStrength.value as number) = this._clamp(
466	      look.motionStrength,
467	      BACKGROUND_MOTION_STRENGTH_MIN,
468	      BACKGROUND_MOTION_STRENGTH_MAX,
469	    );
470	    (uniforms.uLegacyMix.value as number) = this._clamp(
471	      look.legacyMix,
472	      BACKGROUND_LEGACY_MIX_MIN,
473	      BACKGROUND_LEGACY_MIX_MAX,
474	    );
