489	  private _resolveLook(
490	    entry: BackgroundManagerEntry,
491	    variant: BackgroundVariantKey,
492	  ): Required<BackgroundLookOptions> {
493	    if (this._isAboutVariant(variant)) {
494	      return { ...ABOUT_VARIANT_ISOLATED_LOOK };
495	    }
496	    const runtimeLook = entry.runtimeState.look;
497	    if (runtimeLook) {
498	      return this._resolveLookFromSource(runtimeLook);
499	    }
500	    return this._resolveLookFromSource(entry.options.look);
501	  }
502	
503	  private _resolveLookFromSource(
504	    source: BackgroundLookOptions | undefined,
505	  ): Required<BackgroundLookOptions> {
506	    return {
507	      topColor: this._resolveFiniteNumber(
508	        source?.topColor,
509	        BACKGROUND_DEFAULT_LOOK.topColor,
510	      ),
511	      bottomColor: this._resolveFiniteNumber(
512	        source?.bottomColor,
513	        BACKGROUND_DEFAULT_LOOK.bottomColor,
514	      ),
515	      accentColor: this._resolveFiniteNumber(
516	        source?.accentColor,
517	        BACKGROUND_DEFAULT_LOOK.accentColor,
518	      ),
519	      starIntensity: this._resolveFiniteNumber(
520	        source?.starIntensity,
521	        BACKGROUND_DEFAULT_LOOK.starIntensity,
522	      ),
523	      starDensity: this._resolveFiniteNumber(
524	        source?.starDensity,
525	        BACKGROUND_DEFAULT_LOOK.starDensity,
526	      ),
527	      nebulaStrength: this._resolveFiniteNumber(
528	        source?.nebulaStrength,
529	        BACKGROUND_DEFAULT_LOOK.nebulaStrength,
530	      ),
531	      motionStrength: this._resolveFiniteNumber(
532	        source?.motionStrength,
533	        BACKGROUND_DEFAULT_LOOK.motionStrength,
534	      ),
535	      legacyMix: this._resolveFiniteNumber(
536	        source?.legacyMix,
537	        BACKGROUND_DEFAULT_LOOK.legacyMix,
538	      ),
539	    };
540	  }
541	
542	  private _resolveFiniteNumber(value: unknown, fallback: number): number {
543	    if (typeof value === "number" && Number.isFinite(value)) {
544	      return value;
545	    }
546	    return fallback;
547	  }
548	
549	  private _updateAnchor(deltaTime: number): void {
550	    this._cameraEuler.setFromQuaternion(this._camera.quaternion);
551	    const yaw = THREE.MathUtils.clamp(this._cameraEuler.y, -1, 1);
552	    const pitch = THREE.MathUtils.clamp(this._cameraEuler.x, -0.75, 0.75);
553	    this._anchorTarget.set(
554	      0.5 + yaw * BACKGROUND_ANCHOR_X,
555	      0.5 - pitch * BACKGROUND_ANCHOR_Y,
556	    );
557	    const alpha =
558	      1 - Math.exp(-Math.max(0, deltaTime) * BACKGROUND_ANCHOR_DAMPING);
559	    this._anchor.lerp(this._anchorTarget, alpha);
560	  }
561	
562	  private _applyExposure(entry: BackgroundManagerEntry): void {
563	    const exposure = this._resolveExposure(entry);
564	    if (exposure == null) {
565	      this._restoreRendererExposure();
566	      return;
567	    }
568	    if (this._rendererExposureSnapshot == null) {
569	      this._rendererExposureSnapshot = this._renderer.toneMappingExposure;
570	    }
571	    this._renderer.toneMappingExposure = exposure;
572	  }
573	
574	  private _resolveExposure(entry: BackgroundManagerEntry): number | null {
575	    const runtimeExposure = entry.runtimeState.exposure;
576	    if (
577	      typeof runtimeExposure === "number" &&
578	      Number.isFinite(runtimeExposure)
579	    ) {
580	      return this._clamp(runtimeExposure, 0.05, 2.0);
581	    }
582	    const optionExposure = entry.options.exposure;
583	    if (typeof optionExposure === "number" && Number.isFinite(optionExposure)) {
584	      return this._clamp(optionExposure, 0.05, 2.0);
585	    }
586	    return BACKGROUND_DEFAULT_EXPOSURE;
587	  }
588	
589	  private _restoreRendererExposure(): void {
590	    if (this._rendererExposureSnapshot == null) return;
591	    this._renderer.toneMappingExposure = this._rendererExposureSnapshot;
592	    this._rendererExposureSnapshot = null;
593	  }
594	
595	  private _restoreSceneBackground(): void {
596	    this._scene.background = this._cloneSceneBackground(
597	      this._initialBackground,
598	    );
599	    this._scene.backgroundIntensity = 1;
600	  }
601	
602	  private _renderTransition(): void {
603	    this._renderTransitionWithProgress(this._resolveTransitionProgress());
604	  }
605	
606	  private _renderTransitionWithProgress(progress: number): void {
607	    (this._transitionMaterial.uniforms.time.value as number) =
608	      this._elapsedTime;
609	    (this._transitionMaterial.uniforms.progress.value as number) = progress;
610	    (this._transitionMaterial.uniforms.texture1.value as THREE.Texture | null) =
611	      this._transitionFromRenderTarget.texture;
612	    (this._transitionMaterial.uniforms.texture2.value as THREE.Texture | null) =
613	      this._variantRenderTarget.texture;
614	    this._renderFullscreen(this._transitionMaterial, this._displayRenderTarget);
615	  }
616	
617	  private _resolveTransitionProgress(): number {
618	    if (!this._transitionActive) return 1;
619	    const normalized = this._clamp(
620	      this._transitionElapsed / BACKGROUND_TRANSITION_CONFIG.duration,
621	      0,
622	      1,
623	    );
624	    return 1 - Math.pow(1 - normalized, 3);
625	  }
626	
627	  private _copyToTarget(
628	    texture: THREE.Texture,
629	    target: THREE.WebGLRenderTarget,
630	  ): void {
631	    (this._copyMaterial.uniforms.uTexture.value as THREE.Texture | null) =
632	      texture;
633	    this._renderFullscreen(this._copyMaterial, target);
634	  }
635	
636	  private _renderFullscreen(
637	    material: THREE.ShaderMaterial,
638	    target: THREE.WebGLRenderTarget,
639	  ): void {
640	    const previousMaterial = this._mesh.material;
641	    const previousTarget = this._renderer.getRenderTarget();
642	    this._mesh.material = material;
643	    this._renderer.setRenderTarget(target);
644	    this._renderer.clear();
645	    this._renderer.render(this._backgroundScene, this._backgroundCamera);
646	    this._renderer.setRenderTarget(previousTarget);
647	    this._mesh.material = previousMaterial;
648	  }
649	
650	  private _resolveVariant(entry: BackgroundManagerEntry): BackgroundVariantKey {
651	    const variant = entry.runtimeState.variant;
652	    if (variant && BACKGROUND_KNOWN_VARIANTS.has(variant)) {
653	      return variant;
654	    }
655	    const initialVariant = BACKGROUND_INITIAL_VARIANT_BY_ID[entry.id];
656	    if (initialVariant) return initialVariant;
657	    return "story";
658	  }
659	
660	  private _isVisible(options: Partial<BackgroundObjectOptions>): boolean {
661	    return options.visible !== false;
662	  }
663	
664	  private _mergeLook(
665	    current: BackgroundLookOptions | undefined,
666	    next: BackgroundLookOptions | undefined,
667	  ): BackgroundLookOptions | undefined {
668	    if (!current) return next ? { ...next } : undefined;
669	    if (!next) return { ...current };
