671	  }
672	
673	  private _cloneSceneBackground(
674	    background: THREE.Color | THREE.Texture | THREE.CubeTexture | null,
675	  ): THREE.Color | THREE.Texture | THREE.CubeTexture | null {
676	    if (background instanceof THREE.Color) return background.clone();
677	    return background;
678	  }
679	
680	  private _createDisplacementTexture(): THREE.DataTexture {
681	    return this._createNoiseTexture(
682	      BACKGROUND_TRANSITION_CONFIG.displacementTextureSize,
683	    );
684	  }
685	
686	  private _createNoiseTexture(size: number): THREE.DataTexture {
687	    const data = new Uint8Array(size * size * 4);
688	    for (let index = 0; index < data.length; index += 4) {
689	      const value = Math.floor(Math.random() * 255);
690	      data[index] = value;
691	      data[index + 1] = value;
692	      data[index + 2] = value;
693	      data[index + 3] = 255;
694	    }
695	    const texture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
696	    texture.wrapS = THREE.RepeatWrapping;
697	    texture.wrapT = THREE.RepeatWrapping;
698	    texture.magFilter = THREE.LinearFilter;
699	    texture.minFilter = THREE.LinearFilter;
700	    texture.needsUpdate = true;
701	    return texture;
702	  }
703	
704	  private _clamp(value: number, min: number, max: number): number {
705	    return Math.max(min, Math.min(max, value));
706	  }
707	
708	  private _isAboutVariant(variant: BackgroundVariantKey): boolean {
709	    return variant.startsWith("about");
710	  }
