1	import type { Engine } from "../core/Engine.js";
2	import { BackgroundMaterialRuntime } from "../runtime/BackgroundMaterialRuntime.js";
3	import { Helpers } from "../utils/Helpers.js";
4	import { Logger } from "../utils/Logger.js";
5	import type {
6	  BackgroundRuntimePort,
7	  BackgroundTransitionMode,
8	  BackgroundVariantKey,
9	} from "../types/object-runtime.types.js";
10	import type {
11	  SceneBackgroundPolicy,
12	  SceneBackgroundState,
13	} from "../types/runtime.types.js";
14	
15	export class BackgroundController {
16	  private static readonly _CLASS = "BackgroundController";
17	  private _engine: Engine | null = null;
18	  private readonly _lastSheetIdByBackgroundId = new Map<string, string | null>();
19	  private readonly _lastStateByBackgroundId = new Map<string, SceneBackgroundState>();
20	  private _transitionEnabled = true;
21	
22	  bind(engine: Engine): void {
23	    this._engine = engine;
24	  }
25	
26	  setTransitionEnabled(enabled: boolean): void {
27	    this._transitionEnabled = enabled;
28	  }
29	
30	  dispose(): void {
31	    this._engine = null;
32	    this._lastSheetIdByBackgroundId.clear();
33	    this._lastStateByBackgroundId.clear();
34	    this._transitionEnabled = true;
35	  }
36	
37	  sync<TSceneKey extends string, TSheetId extends string>(
38	    sceneKey: TSceneKey,
39	    progress: number,
40	    sheetId: TSheetId | null,
41	    policy: SceneBackgroundPolicy<TSceneKey, TSheetId> | null,
42	  ): void {
43	    if (!policy) return;
44	    const runtime = this._getBackgroundRuntime(policy.backgroundId);
45	    if (!runtime) return;
46	
47	    const state = this._resolveState(sceneKey, progress, sheetId, policy);
48	    const lastState = this._lastStateByBackgroundId.get(policy.backgroundId) ?? null;
49	    const lastSheetId =
50	      this._lastSheetIdByBackgroundId.get(policy.backgroundId) ?? null;
51	    const didStateChange = !this._isSameState(lastState, state);
52	
53	    if (didStateChange) {
54	      runtime.setRuntimeState({
55	        look: state.look ? { ...state.look } : undefined,
56	        variant: state.variant,
57	      });
58	    }
59	
60	    this._resetShaderClockOnEntry(
61	      policy.backgroundId,
62	      lastState?.variant ?? null,
63	      state.variant,
64	      policy.resetShaderClockOnVariant ?? null,
65	    );
66	    if (didStateChange) {
67	      this._startTransitionOnChange(
68	        policy.backgroundId,
69	        lastSheetId,
70	        sheetId,
71	        this._resolveTransitionMode(lastSheetId, sheetId, policy),
72	      );
73	    }
74	    this._logSheetChange(policy.backgroundId, sceneKey, progress, lastSheetId, sheetId, state);
75	    this._lastSheetIdByBackgroundId.set(policy.backgroundId, sheetId);
76	    this._lastStateByBackgroundId.set(policy.backgroundId, this._cloneState(state));
77	  }
78	
79	  private _resolveState<TSceneKey extends string, TSheetId extends string>(
80	    sceneKey: TSceneKey,
81	    progress: number,
82	    sheetId: TSheetId | null,
83	    policy: SceneBackgroundPolicy<TSceneKey, TSheetId>,
84	  ): SceneBackgroundState {
85	    const baseState = this._resolveBaseState(sceneKey, sheetId, policy);
86	    if (!policy.resolveState) {
87	      return this._cloneState(baseState);
88	    }
89	
90	    const resolvedState = policy.resolveState(
91	      {
92	        sceneKey,
93	        progress: Helpers.clamp01(progress),
94	        sheetId,
95	      },
96	      this._cloneState(baseState),
97	    );
98	    return this._cloneState(resolvedState);
99	  }
100	
101	  private _resolveTransitionMode<TSheetId extends string>(
102	    previousKey: string | null,
103	    nextKey: string | null,
104	    policy: SceneBackgroundPolicy<string, TSheetId>,
105	  ): BackgroundTransitionMode {
106	    if (!previousKey || !nextKey) return "crossfade";
107	    const matchedRule = policy.transitionRules?.find((rule) => {
108	      return rule.from === previousKey && rule.to === nextKey;
109	    });
110	    return matchedRule?.mode ?? "crossfade";
111	  }
112	
113	  private _resolveBaseState<TSceneKey extends string, TSheetId extends string>(
114	    sceneKey: TSceneKey,
115	    sheetId: TSheetId | null,
116	    policy: SceneBackgroundPolicy<TSceneKey, TSheetId>,
117	  ): SceneBackgroundState {
118	    const sceneState = policy.statesBySceneKey?.[sceneKey];
119	    if (sceneState) {
120	      return this._cloneState(sceneState);
121	    }
122	    if (!sheetId) {
123	      return this._cloneState(policy.defaultState);
124	    }
125	    return this._cloneState(
126	      policy.statesBySheetId?.[sheetId] ?? policy.defaultState,
127	    );
128	  }
129	
130	  private _cloneState(
131	    state: Readonly<SceneBackgroundState>,
132	  ): SceneBackgroundState {
133	    return {
134	      variant: state.variant,
135	      look: state.look ? { ...state.look } : undefined,
136	    };
137	  }
138	
139	  private _startTransitionOnChange(
140	    backgroundId: string,
141	    previousKey: string | null,
142	    nextKey: string | null,
143	    mode: BackgroundTransitionMode,
144	  ): void {
145	    if (!this._transitionEnabled) return;
146	    if (!previousKey || !nextKey || previousKey === nextKey) {
147	      return;
148	    }
149	    if (mode === "skip") return;
150	    this._engine?.getBackgroundManager()?.startTransition(backgroundId);
151	  }
152	
153	  private _resetShaderClockOnEntry(
154	    backgroundId: string,
155	    previousVariant: BackgroundVariantKey | null,
156	    nextVariant: BackgroundVariantKey,
157	    resetVariant: BackgroundVariantKey | null,
158	  ): void {
159	    if (!resetVariant) return;
160	    if (nextVariant !== resetVariant) return;
161	    if (previousVariant === nextVariant) return;
162	    this._engine?.getBackgroundManager()?.resetShaderClock(backgroundId);
163	  }
164	
165	  private _getBackgroundRuntime(id: string): BackgroundRuntimePort | null {
166	    return this._engine?.getSceneObjectById(id) as BackgroundRuntimePort | null;
167	  }
168	
169	  private _logSheetChange(
170	    backgroundId: string,
171	    sceneKey: string,
172	    progress: number,
173	    previousSheetId: string | null,
174	    nextSheetId: string | null,
175	    state: SceneBackgroundState,
176	  ): void {
177	    if (previousSheetId === nextSheetId) return;
178	    Logger.info(
179	      BackgroundController._CLASS,
180	      "_logSheetChange",
181	      `Background sheet changed -> ${previousSheetId ?? "none"} -> ${nextSheetId ?? "none"} | variant: ${state.variant} | shader: ${BackgroundMaterialRuntime.getFragmentShaderLabel(state.variant)}`,
182	      {
183	        backgroundId,
184	        sceneKey,
185	        previousSheetId,
186	        sheetId: nextSheetId,
187	        variant: state.variant,
188	        shader: BackgroundMaterialRuntime.getFragmentShaderLabel(state.variant),
189	        progress: Number(progress.toFixed(4)),
190	      },
191	    );
192	  }
193	
194	  private _isSameState(
195	    previousState: SceneBackgroundState | null,
196	    nextState: SceneBackgroundState,
197	  ): boolean {
198	    if (!previousState) return false;
199	    if (previousState.variant !== nextState.variant) return false;
200	    return this._isSameLook(previousState.look, nextState.look);
201	  }
202	
203	  private _isSameLook(
204	    previousLook: SceneBackgroundState["look"],
205	    nextLook: SceneBackgroundState["look"],
206	  ): boolean {
207	    if (!previousLook && !nextLook) return true;
208	    if (!previousLook || !nextLook) return false;
209	    return (
210	      previousLook.topColor === nextLook.topColor &&
211	      previousLook.bottomColor === nextLook.bottomColor &&
212	      previousLook.accentColor === nextLook.accentColor &&
213	      previousLook.starIntensity === nextLook.starIntensity &&
214	      previousLook.starDensity === nextLook.starDensity &&
215	      previousLook.nebulaStrength === nextLook.nebulaStrength &&
216	      previousLook.motionStrength === nextLook.motionStrength &&
217	      previousLook.legacyMix === nextLook.legacyMix
218	    );
219	  }
220	}
