1	import { SUBPAGE_STARFIELD } from "../config/component.config.js";
2	import { FrameScheduler } from "../utils/FrameScheduler.js";
3	import { ResponsiveRuntime } from "./ResponsiveRuntime.js";
4	import type { SubpageStarfieldStar } from "../types/component.types.js";
5	
6	export class SubpageStarfieldRuntime {
7	  private _canvas: HTMLCanvasElement | null = null;
8	  private _context: CanvasRenderingContext2D | null = null;
9	  private _stars: SubpageStarfieldStar[] = [];
10	  private _width = 0;
11	  private _height = 0;
12	  private _centerX = 0;
13	  private _centerY = 0;
14	  private _rafId: number | null = null;
15	  private _resizeListener: (() => void) | null = null;
16	  private _scrollListener: (() => void) | null = null;
17	  private _scrollBoost = 0;
18	  private _targetScrollBoost = 0;
19	  private _lastScrollY = 0;
20	  private _lastFrameTime = 0;
21	
22	  init(root?: ParentNode | null): void {
23	    this.dispose();
24	    if (!this._isEligible()) return;
25	    const scope = root ?? document;
26	    const canvas = scope.querySelector<HTMLCanvasElement>(
27	      SUBPAGE_STARFIELD.canvasSelector,
28	    );
29	    if (!canvas) return;
30	    const context = canvas.getContext("2d");
31	    if (!context) return;
32	    this._canvas = canvas;
33	    this._context = context;
34	    this._lastScrollY = window.scrollY ?? window.pageYOffset ?? 0;
35	    this._bindEvents();
36	    this._resize();
37	    this._seedStars();
38	    this._lastFrameTime = performance.now();
39	    this._startLoop();
40	  }
41	
42	  dispose(): void {
43	    if (this._rafId !== null) {
44	      FrameScheduler.cancel(this._rafId);
45	      this._rafId = null;
46	    }
47	    if (this._resizeListener) {
48	      window.removeEventListener("resize", this._resizeListener);
49	      this._resizeListener = null;
50	    }
51	    if (this._scrollListener) {
52	      window.removeEventListener("scroll", this._scrollListener);
53	      this._scrollListener = null;
54	    }
55	    this._canvas = null;
56	    this._context = null;
57	    this._stars = [];
58	    this._width = 0;
59	    this._height = 0;
60	    this._centerX = 0;
61	    this._centerY = 0;
62	    this._scrollBoost = 0;
63	    this._targetScrollBoost = 0;
64	    this._lastScrollY = 0;
65	    this._lastFrameTime = 0;
66	  }
67	
68	  private _isEligible(): boolean {
69	    const pathname = window.location.pathname || "/";
70	    return SUBPAGE_STARFIELD.pagePrefixes.some((prefix) =>
71	      pathname.startsWith(prefix),
72	    );
73	  }
74	
75	  private _bindEvents(): void {
76	    this._resizeListener = () => this._resize();
77	    this._scrollListener = () => this._syncScrollBoost();
78	    window.addEventListener("resize", this._resizeListener);
79	    window.addEventListener("scroll", this._scrollListener, { passive: true });
80	  }
81	
82	  private _resize(): void {
83	    if (!this._canvas || !this._context) return;
84	    const bounds = this._canvas.getBoundingClientRect();
85	    const width = Math.max(1, Math.round(bounds.width));
86	    const height = Math.max(1, Math.round(bounds.height));
87	    const dpr = Math.min(
88	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
89	      SUBPAGE_STARFIELD.pixelRatioMax,
90	    );
91	    this._width = width;
92	    this._height = height;
93	    this._centerX = width * 0.5;
94	    this._centerY = height * 0.5;
95	    this._canvas.width = Math.round(width * dpr);
96	    this._canvas.height = Math.round(height * dpr);
97	    this._context.setTransform(dpr, 0, 0, dpr, 0, 0);
98	  }
99	
100	  private _syncScrollBoost(): void {
101	    const nextY = window.scrollY ?? window.pageYOffset ?? 0;
102	    const delta = Math.abs(nextY - this._lastScrollY);
103	    this._lastScrollY = nextY;
104	    const viewportHeight = Math.max(window.innerHeight || 0, 1);
105	    const normalizedBoost = Math.min(
106	      (delta / viewportHeight) * SUBPAGE_STARFIELD.scrollBoostFactor,
107	      SUBPAGE_STARFIELD.scrollBoostMax,
108	    );
109	    this._targetScrollBoost = Math.max(this._targetScrollBoost, normalizedBoost);
110	  }
111	
112	  private _seedStars(): void {
113	    this._stars = Array.from(
114	      { length: SUBPAGE_STARFIELD.starCount },
115	      () => this._createStar(),
116	    );
117	  }
118	
119	  private _startLoop(): void {
120	    const render = (): void => {
121	      this._render();
122	      this._rafId = FrameScheduler.request(render);
123	    };
124	    render();
125	  }
126	
127	  private _render(): void {
128	    if (!this._context || this._width <= 0 || this._height <= 0) {
129	      return;
130	    }
131	    const now = performance.now();
132	    const delta = Math.min((now - this._lastFrameTime) / 1000, 1 / 24);
133	    this._lastFrameTime = now;
134	    this._targetScrollBoost = Math.max(
135	      0,
136	      this._targetScrollBoost - delta * SUBPAGE_STARFIELD.scrollBoostDecayPerSecond,
137	    );
138	    const lerpFactor = Math.min(
139	      1,
140	      delta * SUBPAGE_STARFIELD.scrollBoostLerpPerSecond,
141	    );
142	    this._scrollBoost +=
143	      (this._targetScrollBoost - this._scrollBoost) * lerpFactor;
144	
145	    const context = this._context;
146	    const speed = SUBPAGE_STARFIELD.speed + this._scrollBoost;
147	    context.fillStyle = `rgba(0, 0, 0, ${SUBPAGE_STARFIELD.clearAlpha})`;
148	    context.fillRect(0, 0, this._width, this._height);
149	
150	    for (const star of this._stars) {
151	      star.z -= speed;
152	      if (star.z <= 0) {
153	        this._resetStar(star);
154	      }
155	
156	      const screenX = (star.x / star.z) * this._width + this._centerX;
157	      const screenY = (star.y / star.z) * this._height + this._centerY;
158	      const previousX = (star.x / star.previousZ) * this._width + this._centerX;
159	      const previousY = (star.y / star.previousZ) * this._height + this._centerY;
160	      const brightness = Math.max(
161	        0,
162	        Math.min(
163	          255,
164	          Math.floor((1 - star.z / (this._width * SUBPAGE_STARFIELD.depthRangeFactor)) * 255),
165	        ),
166	      );
167	      const radius = Math.max(
168	        SUBPAGE_STARFIELD.radiusMin,
169	        (1 - star.z / (this._width * SUBPAGE_STARFIELD.depthRangeFactor)) *
170	          SUBPAGE_STARFIELD.radiusMax,
171	      );
172	
173	      context.beginPath();
174	      context.moveTo(previousX, previousY);
175	      context.lineTo(screenX, screenY);
176	      context.strokeStyle = `rgba(${brightness}, ${brightness}, ${brightness}, 1)`;
177	      context.lineWidth = radius;
178	      context.stroke();
179	
180	      star.previousZ = star.z;
181	    }
182	  }
183	
184	  private _createStar(): SubpageStarfieldStar {
185	    return this._resetStar({
186	      x: 0,
187	      y: 0,
188	      z: 0,
189	      previousZ: 0,
190	    });
191	  }
192	
193	  private _resetStar(star: SubpageStarfieldStar): SubpageStarfieldStar {
194	    star.x = (Math.random() - 0.5) * this._width;
195	    star.y = (Math.random() - 0.5) * this._height;
196	    star.z = Math.random() * (this._width * SUBPAGE_STARFIELD.depthRangeFactor);
197	    star.previousZ = star.z;
198	    return star;
199	  }
200	}
