205	  private _addLight(spec: LightSpec): void {
206	    if (!spec.id) return;
207	    const parent = this._groups.rig;
208	    if (!parent) return;
209	
210	    const color = spec.color ?? 0xffffff;
211	    const intensity = Number.isFinite(spec.intensity as number)
212	      ? Number(spec.intensity)
213	      : 1;
214	    const type = (spec.type ?? "directional").toLowerCase();
215	    let light: THREE.Light;
216	
217	    if (type === "ambient") {
218	      light = new THREE.AmbientLight(color, intensity);
219	    } else if (type === "point") {
220	      light = createPointLightFromSpec(spec, color, intensity);
221	      this._applyPosition(light, spec.position);
222	    } else if (type === "spot") {
223	      const spot = new THREE.SpotLight(
224	        color,
225	        intensity,
226	        spec.distance,
227	        spec.angle,
228	        spec.penumbra,
229	        spec.decay,
230	      );
231	      this._applyPosition(spot, spec.position);
232	      this._applyDirectionalTarget(parent, spot, spec.target);
233	      this._applyShadow(spot, spec);
234	      light = spot;
235	    } else {
236	      const directional = new THREE.DirectionalLight(color, intensity);
237	      this._applyPosition(directional, spec.position);
238	      this._applyDirectionalTarget(parent, directional, spec.target);
239	      this._applyShadow(directional, spec);
240	      light = directional;
241	    }
242	
243	    this._attachEmitter(light, spec);
244	    light.name = `aboutLight:${spec.id}`;
245	    light.layers.set(THREE_LAYER_DEFAULT);
246	    if (spec.affectsEarth !== false) {
247	      light.layers.enable(THREE_LAYER_EARTH);
248	    }
249	    if (
250	      (light instanceof THREE.DirectionalLight ||
251	        light instanceof THREE.SpotLight) &&
252	      light.target
253	    ) {
254	      light.target.layers.set(THREE_LAYER_DEFAULT);
255	      if (spec.affectsEarth !== false) {
256	        light.target.layers.enable(THREE_LAYER_EARTH);
257	      }
258	    }
259	    parent.add(light);
260	    this._lights.set(spec.id, light);
261	  }
