263	  private _attachEmitter(light: THREE.Light, spec: LightSpec): void {
264	    const emitter = spec.emitter;
265	    if (emitter?.enabled === false) return;
266	    if (!emitter) return;
267	
268	    const radius = Math.max(0.001, emitter.radius ?? 0.045);
269	    const color = emitter.color ?? spec.color ?? 0xffffff;
270	    const opacity = Math.max(0, Math.min(1, emitter.opacity ?? 0.95));
271	    const haloScale = Math.max(1, emitter.haloScale ?? 2.8);
272	    const haloOpacity = Math.max(0, Math.min(1, emitter.haloOpacity ?? 0.18));
273	
274	    const coreGeometry = new THREE.SphereGeometry(
275	      radius,
276	      AboutLights.EMITTER_HALO_SEGMENTS,
277	      AboutLights.EMITTER_HALO_SEGMENTS,
278	    );
279	    const coreMaterial = new THREE.MeshBasicMaterial({
280	      color,
281	      transparent: opacity < 1,
282	      opacity,
283	      toneMapped: false,
284	      depthWrite: false,
285	    });
286	    const core = new THREE.Mesh(coreGeometry, coreMaterial);
287	    core.name = `${light.name || spec.id}:emitter-core`;
288	    core.renderOrder = 20;
289	
290	    const haloGeometry = new THREE.SphereGeometry(
291	      radius * haloScale,
292	      AboutLights.EMITTER_HALO_SEGMENTS,
293	      AboutLights.EMITTER_HALO_SEGMENTS,
294	    );
295	    const haloMaterial = new THREE.MeshBasicMaterial({
296	      color,
297	      transparent: true,
298	      opacity: haloOpacity,
299	      blending: THREE.AdditiveBlending,
300	      side: THREE.DoubleSide,
301	      toneMapped: false,
302	      depthWrite: false,
303	    });
304	    const halo = new THREE.Mesh(haloGeometry, haloMaterial);
305	    halo.name = `${light.name || spec.id}:emitter-halo`;
306	    halo.renderOrder = 19;
307	
308	    light.add(core);
309	    light.add(halo);
310	  }
