427	  private _readProxyLightIntensityValue(id: string): number {
428	    const proxy = this._timelineProxy as unknown as Record<string, unknown>;
429	    const value = proxy[id];
430	    if (typeof value === "number" && Number.isFinite(value)) {
431	      return value;
432	    }
433	    const light = this._lights.get(id);
434	    if (!light) return 0;
