444	  private _setProfileStops(
445	    stops: AboutLightsObjectOptions["profileStops"],
446	  ): void {
447	    if (!Array.isArray(stops)) {
448	      this._profileStops = [];
449	      return;
450	    }
451	    this._profileStops = stops
452	      .filter(
453	        (stop): stop is AboutLightProfileStop =>
454	          stop != null &&
455	          Number.isFinite(stop.progress) &&
456	          stop.values != null &&
457	          typeof stop.values === "object",
458	      )
459	      .map((stop) => ({
460	        progress: Math.max(0, Math.min(1, stop.progress)),
461	        values: { ...stop.values },
462	      }))
463	      .sort((a, b) => a.progress - b.progress);
464	  }
465	
466	  private _applyProfileByProgress(): void {
467	    if (this._profileStops.length === 0) return;
468	    const sampled = this._sampleProfile(this._travelProgress);
469	    if (!sampled) return;
470	    const [left, right, t] = sampled;
471	    const keys = new Set<string>([
472	      ...Object.keys(left.values),
473	      ...Object.keys(right.values),
474	    ]);
475	    for (const key of keys) {
476	      if (key === "travelProgress" || key === "intensity") continue;
477	      const leftValue = left.values[key];
478	      const rightValue = right.values[key];
479	      if (
480	        !Number.isFinite(leftValue as number) &&
481	        !Number.isFinite(rightValue as number)
482	      ) {
483	        continue;
484	      }
485	      const l = Number.isFinite(leftValue as number)
486	        ? Number(leftValue)
487	        : Number(rightValue);
488	      const r = Number.isFinite(rightValue as number) ? Number(rightValue) : l;
489	      this._applyLightIntensityValue(key, l + (r - l) * t);
490	    }
491	  }
492	
493	  private _sampleProfile(
494	    progress: number,
495	  ): [AboutLightProfileStop, AboutLightProfileStop, number] | null {
496	    const stops = this._profileStops;
497	    if (stops.length === 0) return null;
498	    if (stops.length === 1) return [stops[0], stops[0], 0];
499	    const clamped = Math.max(0, Math.min(1, progress));
500	    if (clamped <= stops[0].progress) return [stops[0], stops[0], 0];
501	    const last = stops[stops.length - 1];
502	    if (clamped >= last.progress) return [last, last, 0];
503	    for (let index = 0; index < stops.length - 1; index += 1) {
504	      const left = stops[index];
505	      const right = stops[index + 1];
506	      if (clamped < left.progress || clamped > right.progress) continue;
507	      const span = Math.max(Number.EPSILON, right.progress - left.progress);
508	      return [left, right, (clamped - left.progress) / span];
509	    }
510	    return [last, last, 0];
511	  }
