513	  private _syncProxyLightBaseIntensities(): void {
514	    const proxy = this._timelineProxy as unknown as Record<string, unknown>;
515	    const master = Math.max(1e-6, this._masterIntensity);
516	    for (const [id, light] of this._lights.entries()) {
517	      proxy[id] = light.intensity / master;
518	    }
519	  }
