527	  private _buildFollowCameraEntries(): void {
528	    this._followCameraEntries = [];
529	    const camera = this._context?.camera;
530	    if (!(camera instanceof THREE.Object3D)) return;
531	
532	    const camPos = new THREE.Vector3();
533	    const camQuat = new THREE.Quaternion();
534	    const camInvQuat = new THREE.Quaternion();
535	    camera.getWorldPosition(camPos);
536	    camera.getWorldQuaternion(camQuat);
537	    camInvQuat.copy(camQuat).invert();
538	
539	    for (const spec of this._specs) {
540	      const rawFollow = spec.followCamera;
541	      const followOpts =
542	        typeof rawFollow === "object" && rawFollow != null ? rawFollow : null;
543	      const enabled = rawFollow === true || followOpts?.enabled === true;
544	      if (!enabled) continue;
545	
546	      const light = this._lights.get(spec.id);
547	      if (!light) continue;
548	      const rotateWithCamera = followOpts?.rotateWithCamera ?? true;
549	      const lightType = (spec.type ?? "directional").toLowerCase();
550	      const hasTarget = lightType === "directional" || lightType === "spot";
551	      const targetObj =
552	        hasTarget &&
553	        (light instanceof THREE.DirectionalLight ||
554	          light instanceof THREE.SpotLight)
555	          ? light.target
556	          : null;
557	
558	      const positionOffset = followOpts?.positionOffset
559	        ? new THREE.Vector3(
560	            followOpts.positionOffset.x ?? 0,
561	            followOpts.positionOffset.y ?? 0,
562	            followOpts.positionOffset.z ?? 0,
563	          )
564	        : this._worldDeltaToOffset(
565	            light.position.clone().sub(camPos),
566	            rotateWithCamera,
567	            camInvQuat,
568	          );
569	
570	      const targetOffset =
571	        targetObj != null
572	          ? followOpts?.targetOffset
573	            ? new THREE.Vector3(
574	                followOpts.targetOffset.x ?? 0,
575	                followOpts.targetOffset.y ?? 0,
576	                followOpts.targetOffset.z ?? 0,
577	              )
578	            : this._worldDeltaToOffset(
579	                targetObj.position.clone().sub(camPos),
580	                rotateWithCamera,
581	                camInvQuat,
582	              )
583	          : null;
584	
585	      this._followCameraEntries.push({
586	        lightId: spec.id,
587	        rotateWithCamera,
588	        positionOffset,
589	        targetOffset,
590	      });
591	    }
592	  }
593	
594	  private _worldDeltaToOffset(
595	    delta: THREE.Vector3,
596	    rotateWithCamera: boolean,
597	    camInvQuat: THREE.Quaternion,
598	  ): THREE.Vector3 {
599	    if (!rotateWithCamera) return delta;
600	    return delta.applyQuaternion(camInvQuat);
601	  }
602	
603	  private _applyCameraFollow(): void {
604	    if (this._followCameraEntries.length === 0) return;
605	    const camera = this._context?.camera;
606	    if (!(camera instanceof THREE.Object3D)) return;
607	
608	    const camPos = this._followCamPos;
609	    const camQuat = this._followCamQuat;
610	    const worldOffset = this._followWorldOffset;
611	    camera.getWorldPosition(camPos);
612	    camera.getWorldQuaternion(camQuat);
613	
614	    for (const entry of this._followCameraEntries) {
615	      const light = this._lights.get(entry.lightId);
616	      if (!light) continue;
617	
618	      if (entry.positionOffset) {
619	        worldOffset.copy(entry.positionOffset);
620	        if (entry.rotateWithCamera) worldOffset.applyQuaternion(camQuat);
621	        light.position.copy(camPos).add(worldOffset);
622	      }
623	
624	      if (
625	        entry.targetOffset &&
626	        (light instanceof THREE.DirectionalLight ||
627	          light instanceof THREE.SpotLight) &&
628	        light.target
629	      ) {
630	        worldOffset.copy(entry.targetOffset);
631	        if (entry.rotateWithCamera) worldOffset.applyQuaternion(camQuat);
632	        light.target.position.copy(camPos).add(worldOffset);
633	      }
634	    }
635	  }
636	
637	  private _disposeLightDecorators(): void {
638	    for (const light of this._lights.values()) {
639	      for (const child of [...light.children]) {
640	        light.remove(child);
641	        child.traverse((node) => {
642	          if (!(node instanceof THREE.Mesh)) return;
643	          node.geometry?.dispose();
644	          const material = Array.isArray(node.material)
645	            ? node.material
646	            : [node.material];
647	          for (const item of material) {
648	            item?.dispose?.();
649	          }
650	        });
651	      }
652	    }
653	  }
654	
655	  private _createDefaultGroupProxy(): GroupTransformProxy {
656	    return {
657	      position: { x: 0, y: 0, z: 0 },
658	      rotation: { x: 0, y: 0, z: 0 },
659	      scale: { x: 1, y: 1, z: 1 },
660	    };
661	  }
662	}
