39	      this._draco = new DRACOLoader();
40	      
41	      this._draco.setDecoderPath(
42	        "https://www.gstatic.com/draco/versioned/decoders/1.5.7/",
43	      );
44	      this._gltf.setDRACOLoader(this._draco);
45	    } catch (error) {
46	      this._draco = null;
47	    }
48	  }
49	
50	  
51	  clearModelCache(): void {
52	    this._modelMap.clear();
53	    this._clipMap.clear();
54	  }
55	
56	  dispose(): void {
57	    this._modelMap.clear();
58	    this._clipMap.clear();
59	    this._draco?.dispose();
60	    this._draco = null;
61	  }
62	
63	  loadGLTF(
64	    scene: THREE.Scene | null,
65	    url: string,
66	    options: LoadGLTFOptions = {},
67	  ): Promise<LoadGLTFResult> {
68	    const cached = this._modelMap.get(url);
69	    if (cached) {
70	      const clone = cached.clone(true) as THREE.Group;
71	      this._applyTransform(clone, options);
72	      const clips = this._clipMap.get(url) ?? [];
73	      const mixers =
74	        clips.length > 0 ? this._createMixersFromClips(clips, clone) : [];
75	      return Promise.resolve({ model: clone, mixers });
76	    }
77	
78	    if (!scene) return Promise.resolve({ model: null, mixers: [] });
79	    return new Promise<LoadGLTFResult>((resolve, reject) => {
80	      this._gltf.load(
81	        url,
82	        (gltf) => {
83	          const model = gltf.scene;
84	          this._applyTransform(model, options);
85	          this._setupModelUserData(model);
86	          this._setupMeshes(model);
87	          this._modelMap.set(url, model);
88	          this._clipMap.set(url, gltf.animations ?? []);
89	          if (options.addToScene !== false) scene.add(model);
90	          const mixers = this._createMixers(gltf, model);
91	          resolve({ model, mixers });
92	        },
93	        undefined,
94	        reject,
95	      );
96	    });
97	  }
98	
99	  async loadTexture(url: string): Promise<THREE.Texture> {
100	    return new Promise<THREE.Texture>((resolve, reject) => {
101	      this._texture.load(url, resolve, undefined, reject);
102	    });
103	  }
104	
105	  async loadHdrTexture(url: string): Promise<THREE.Texture> {
106	    return this._hdr.loadAsync(url);
107	  }
108	
109	  private _applyTransform(model: THREE.Group, options: LoadGLTFOptions): void {
110	    if (options.position) model.position.set(...options.position);
111	    if (options.scale) model.scale.set(...options.scale);
112	    if (options.rotation) model.rotation.set(...options.rotation);
113	  }
114	
115	  private _setupModelUserData(model: THREE.Object3D): void {
116	    model.userData.selectable = true;
117	    model.userData.isModel = true;
118	  }
119	
120	  private _setupMeshes(model: THREE.Object3D): void {
121	    model.traverse((child) => {
122	      if (!(child as THREE.Mesh).isMesh) return;
123	      const mesh = child as THREE.Mesh;
124	      mesh.userData.selectable = true;
125	      mesh.userData.isModel = true;
126	    });
127	  }
128	
129	  private _createMixers(
130	    gltf: { animations?: THREE.AnimationClip[] },
131	    model: THREE.Object3D,
132	  ): THREE.AnimationMixer[] {
133	    const mixers: THREE.AnimationMixer[] = [];
134	    if (!gltf.animations?.length) return mixers;
135	    const mixer = new THREE.AnimationMixer(model);
136	    gltf.animations.forEach((anim) => mixer.clipAction(anim).play());
137	    mixers.push(mixer);
138	    return mixers;
139	  }
140	
141	  private _createMixersFromClips(
142	    clips: THREE.AnimationClip[],
143	    model: THREE.Object3D,
144	  ): THREE.AnimationMixer[] {
145	    if (clips.length === 0) return [];
146	    const mixer = new THREE.AnimationMixer(model);
147	    clips.forEach((clip) => mixer.clipAction(clip).play());
148	    return [mixer];
149	  }
150	}
