1	import * as THREE from "three";
2	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
3	import type { Engine } from "../core/Engine.js";
4	import type {
5	  ShaderEntryProxy,
6	  ShaderEntryState,
7	  ShaderManagerDebugProxy,
8	  ShaderManagerPort,
9	  ShaderManagerRuntimePort,
10	  ShaderRegistration,
11	  ShaderScalarValue,
12	  ShaderUniformMap,
13	} from "../types/shader.types.js";
14	
15	const SHADER_MANAGER_ID = "env.shaderManager";
16	const SHADER_MANAGER_RUNTIME_ID = "env.shaderManager.runtime";
17	const SHADER_PROXY_PREFIX = "shader.";
18	const FRAME_TIME_SMOOTHING = 0.12;
19	const HIGH_QUALITY_MAX_FRAME_MS = 18;
20	const MID_QUALITY_MAX_FRAME_MS = 28;
21	
22	export class ShaderManager implements ShaderManagerPort {
23	  private _engine: Engine | null = null;
24	  private _entries = new Map<string, ShaderEntryState>();
25	  private _forcedQualityTier: number | null = null;
26	  private readonly _runtimeProxy: ShaderManagerRuntimePort &
27	    Record<string, unknown> = {
28	    register: (registration: ShaderRegistration) => this.register(registration),
29	    unregister: (key: string) => this.unregister(key),
30	    release: (ownerId: string) => this.release(ownerId),
31	    setEnabled: (enabled: boolean) => this.setEnabled(enabled),
32	    setPaused: (paused: boolean) => this.setPaused(paused),
33	    setAutoOptimize: (enabled: boolean) => this.setAutoOptimize(enabled),
34	    forceQualityTier: (qualityTier: number) => this.forceQualityTier(qualityTier),
35	    clearForcedQualityTier: () => this.clearForcedQualityTier(),
36	    getDebugState: () => this.getDebugState(),
37	  };
38	  private _debugProxy: ShaderManagerDebugProxy = {
39	    enabled: true,
40	    paused: false,
41	    autoOptimize: true,
42	    qualityTier: 2,
43	    updateIntervalMs: 16,
44	    trackedMaterials: 0,
45	    lastFrameMs: 16,
46	    averageFrameMs: 16,
47	    elapsedSeconds: 0,
48	    uniformUpdates: 0,
49	  };
50	  private _elapsedSeconds = 0;
51	  private _accumulatedMs = 0;
52	
53	  bind(engine: Engine): void {
54	    this._engine = engine;
55	    const scene = engine.getScene();
56	    scene.registerObject(SHADER_MANAGER_ID, this._debugProxy);
57	    scene.registerObject(SHADER_MANAGER_RUNTIME_ID, this._runtimeProxy);
58	  }
59	
60	  update(deltaTime: number): void {
61	    if (!this._debugProxy.enabled) return;
62	    if (this._debugProxy.paused) return;
63	    if (!Number.isFinite(deltaTime) || deltaTime <= 0) return;
64	
65	    const frameMs = deltaTime * 1000;
66	    this._debugProxy.lastFrameMs = frameMs;
67	    this._debugProxy.averageFrameMs =
68	      this._debugProxy.averageFrameMs +
69	      (frameMs - this._debugProxy.averageFrameMs) * FRAME_TIME_SMOOTHING;
70	    this._elapsedSeconds += deltaTime;
71	    this._debugProxy.elapsedSeconds = this._elapsedSeconds;
72	    if (this._forcedQualityTier != null) {
73	      this._applyForcedQualityTier();
74	    } else if (this._debugProxy.autoOptimize) {
75	      this._optimize(frameMs);
76	    }
77	
78	    this._accumulatedMs += frameMs;
79	    if (this._accumulatedMs < this._debugProxy.updateIntervalMs) return;
80	    this._accumulatedMs = 0;
81	
82	    let uniformUpdates = 0;
83	    for (const entry of this._entries.values()) {
84	      uniformUpdates += this._updateEntry(entry);
85	    }
86	    this._debugProxy.uniformUpdates = uniformUpdates;
87	    this._debugProxy.trackedMaterials = this._entries.size;
88	  }
89	
90	  register(registration: ShaderRegistration): void {
91	    this.unregister(registration.key);
92	    const proxy = this._createEntryProxy(registration);
93	    const entry: ShaderEntryState = {
94	      key: registration.key,
95	      ownerId: registration.ownerId,
96	      material: registration.material,
97	      proxy,
98	      onOptimize: registration.onOptimize,
99	    };
100	    this._entries.set(registration.key, entry);
101	    entry.onOptimize?.(this._debugProxy.qualityTier, entry.material);
102	    this._engine
103	      ?.getScene()
104	      .registerObject(`${SHADER_PROXY_PREFIX}${registration.key}`, proxy);
105	    this._debugProxy.trackedMaterials = this._entries.size;
106	  }
107	
108	  unregister(key: string): void {
109	    const existing = this._entries.get(key);
110	    if (!existing) return;
111	    this._entries.delete(key);
112	    this._engine
113	      ?.getScene()
114	      .unregisterObject(`${SHADER_PROXY_PREFIX}${existing.key}`);
115	    this._debugProxy.trackedMaterials = this._entries.size;
116	  }
117	
118	  release(ownerId: string): void {
119	    const keys = Array.from(this._entries.values())
120	      .filter((entry) => entry.ownerId === ownerId)
121	      .map((entry) => entry.key);
122	    keys.forEach((key) => this.unregister(key));
123	  }
124	
125	  dispose(): void {
126	    for (const key of Array.from(this._entries.keys())) {
127	      this.unregister(key);
128	    }
129	    this._engine?.getScene().unregisterObject(SHADER_MANAGER_ID);
130	    this._engine?.getScene().unregisterObject(SHADER_MANAGER_RUNTIME_ID);
131	    this._engine = null;
132	    this._elapsedSeconds = 0;
133	    this._accumulatedMs = 0;
134	    this._forcedQualityTier = null;
135	  }
136	
137	  setEnabled(enabled: boolean): void {
138	    this._debugProxy.enabled = enabled;
139	  }
140	
141	  setPaused(paused: boolean): void {
142	    this._debugProxy.paused = paused;
143	  }
144	
145	  setAutoOptimize(enabled: boolean): void {
146	    this._debugProxy.autoOptimize = enabled;
147	  }
148	
149	  forceQualityTier(qualityTier: number): void {
150	    const normalized = this._normalizeQualityTier(qualityTier);
151	    this._forcedQualityTier = normalized;
152	    this._debugProxy.autoOptimize = false;
153	    this._setQuality(normalized, this._resolveIntervalMs(normalized));
154	  }
155	
156	  clearForcedQualityTier(): void {
157	    this._forcedQualityTier = null;
158	    this._debugProxy.autoOptimize = true;
159	  }
160	
161	  getDebugState(): ShaderManagerDebugProxy {
162	    return this._debugProxy;
163	  }
164	
165	  private _optimize(frameMs: number): void {
166	    if (frameMs <= HIGH_QUALITY_MAX_FRAME_MS) {
167	      this._setQuality(2, 16);
168	      return;
169	    }
170	    if (frameMs <= MID_QUALITY_MAX_FRAME_MS) {
171	      this._setQuality(1, 33);
172	      return;
173	    }
174	    this._setQuality(0, 66);
175	  }
176	
177	  private _setQuality(qualityTier: number, updateIntervalMs: number): void {
178	    const changed = this._debugProxy.qualityTier !== qualityTier;
179	    this._debugProxy.qualityTier = qualityTier;
180	    this._debugProxy.updateIntervalMs = updateIntervalMs;
181	    if (!changed) return;
182	    for (const entry of this._entries.values()) {
183	      entry.onOptimize?.(qualityTier, entry.material);
184	    }
185	  }
186	
187	  private _applyForcedQualityTier(): void {
188	    if (this._forcedQualityTier == null) return;
189	    this._setQuality(
190	      this._forcedQualityTier,
191	      this._resolveIntervalMs(this._forcedQualityTier),
192	    );
193	  }
194	
195	  private _normalizeQualityTier(qualityTier: number): number {
196	    if (qualityTier <= 0) return 0;
197	    if (qualityTier >= 2) return 2;
198	    return 1;
199	  }
200	
201	  private _resolveIntervalMs(qualityTier: number): number {
202	    if (qualityTier >= 2) return 16;
203	    if (qualityTier === 1) return 33;
204	    return 66;
205	  }
206	
207	  private _updateEntry(entry: ShaderEntryState): number {
208	    if (!entry.proxy.enabled) return 0;
209	    const uniforms = entry.material.uniforms;
210	    if (!uniforms) return 0;
211	
212	    let updates = 0;
213	    if (entry.proxy.autoTime) {
214	      updates += this._applyTimeUniform(uniforms, "uTime", entry.proxy.timeScale);
215	      updates += this._applyTimeUniform(uniforms, "iTime", entry.proxy.timeScale);
216	    }
217	    if (entry.proxy.autoResolution) {
218	      updates += this._applyResolutionUniform(uniforms, "uResolution");
219	      updates += this._applyResolutionUniform(uniforms, "iResolution");
220	    }
221	    this._defineUniformProxy(entry.proxy, uniforms);
222	    entry.proxy.uniformCount = Object.keys(uniforms).length;
223	    return updates;
224	  }
225	
226	  private _applyTimeUniform(
227	    uniforms: ShaderUniformMap,
228	    key: string,
229	    timeScale: number,
230	  ): number {
231	    const uniform = uniforms[key];
232	    if (!uniform || typeof uniform.value !== "number") return 0;
233	    uniform.value = this._elapsedSeconds * timeScale;
234	    return 1;
235	  }
236	
237	  private _applyResolutionUniform(
238	    uniforms: ShaderUniformMap,
239	    key: string,
240	  ): number {
241	    const uniform = uniforms[key];
242	    if (!uniform) return 0;
243	    const value = uniform.value;
244	    if (!(value instanceof THREE.Vector2)) return 0;
245	    const renderer = this._engine?.getRenderer();
246	      const width =
247	        renderer instanceof THREE.WebGLRenderer
248	          ? renderer.domElement.width
249	        : ResponsiveRuntime.getDefault().getSnapshot().viewportWidth;
250	      const height =
251	        renderer instanceof THREE.WebGLRenderer
252	          ? renderer.domElement.height
253	        : ResponsiveRuntime.getDefault().getSnapshot().viewportHeight;
254	      value.set(width, height);
255	      return 1;
256	    }
257	
258	  private _createEntryProxy(
259	    registration: ShaderRegistration,
260	  ): ShaderEntryProxy {
261	    const proxy: ShaderEntryProxy = {
262	      enabled: true,
263	      autoTime: registration.autoTime ?? true,
264	      autoResolution: registration.autoResolution ?? true,
265	      timeScale: registration.timeScale ?? 1,
266	      uniformCount: Object.keys(registration.material.uniforms ?? {}).length,
267	    };
268	    this._defineUniformProxy(proxy, registration.material.uniforms);
269	    return proxy;
270	  }
271	
272	  private _defineUniformProxy(
273	    proxy: ShaderEntryProxy,
274	    uniforms: ShaderUniformMap,
275	  ): void {
276	    for (const [key, uniform] of Object.entries(uniforms)) {
277	      const isNumber = typeof uniform.value === "number";
278	      const isBoolean = typeof uniform.value === "boolean";
279	      if (!isNumber && !isBoolean) continue;
280	      if (Object.prototype.hasOwnProperty.call(proxy, key)) continue;
281	      Object.defineProperty(proxy, key, {
282	        enumerable: true,
283	        configurable: true,
284	        get: () => uniform.value as ShaderScalarValue,
285	        set: (value: ShaderScalarValue) => {
286	          if (isNumber && typeof value === "number" && Number.isFinite(value)) {
287	            uniform.value = value;
288	          }
289	          if (isBoolean && typeof value === "boolean") {
290	            uniform.value = value;
291	          }
292	        },
293	      });
294	    }
295	  }
296	}
