392	  ): THREE.Object3D | null {
393	    const normalizedIncludes = this._getNormalizedFlameAnchorIncludes(options);
394	    let bestMatch: THREE.Object3D | null = null;
395	
396	    model.traverse((child) => {
397	      if (bestMatch || child === model) return;
398	      const normalizedName = child.name.trim().toLowerCase();
399	      if (!normalizedName) return;
400	      if (!normalizedIncludes.some((value) => normalizedName.includes(value)))
401	        return;
402	      bestMatch = child;
403	    });
404	
405	    if (!bestMatch) {
406	      Logger.warn(
407	        ROCKET_CLASS,
408	        "runObject",
409	        "Rocket flame anchor was not found by name. Falling back to bounding-box placement.",
410	      );
411	    }
412	
413	    return bestMatch;
414	  }
