38	  private _applyFalloffShader(group: THREE.Group): void {
39	    this._shaderRefs = [];
40	    group.traverse((child) => {
41	      if (!(child instanceof THREE.Mesh)) return;
42	      const material = child.material;
43	      if (!(material instanceof THREE.MeshStandardMaterial)) return;
44	      const nextMaterial = material.clone();
45	      child.material = nextMaterial;
46	
47	      nextMaterial.onBeforeCompile = (shader) => {
48	        shader.uniforms.uAboutFalloffCenter = {
49	          value: this._falloffCenter,
50	        };
51	        shader.uniforms.uAboutFalloffInnerRadius = {
52	          value: ABOUT_TERRIAN_FALLOFF.innerRadius,
53	        };
54	        shader.uniforms.uAboutFalloffOuterRadius = {
55	          value: ABOUT_TERRIAN_FALLOFF.outerRadius,
56	        };
57	        shader.uniforms.uAboutFalloffBrightness = {
58	          value: ABOUT_TERRIAN_FALLOFF.brightness,
59	        };
60	        shader.uniforms.uAboutFalloffDarkness = {
61	          value: ABOUT_TERRIAN_FALLOFF.darkness,
62	        };
63	        shader.uniforms.uAboutFalloffBlendPower = {
64	          value: ABOUT_TERRIAN_FALLOFF.blendPower,
65	        };
66	
67	        shader.vertexShader = shader.vertexShader
68	          .replace(
69	            "#include <common>",
70	            aboutTerrianFalloffVertexShader,
71	          )
72	          .replace(
73	            "#include <begin_vertex>",
74	            aboutTerrianFalloffBeginVertexShader,
75	          );
76	
77	        shader.fragmentShader = shader.fragmentShader
78	          .replace(
79	            "#include <common>",
80	            aboutTerrianFalloffFragmentShader,
81	          )
82	          .replace(
83	            "#include <output_fragment>",
84	            aboutTerrianFalloffOutputFragmentShader,
85	          );
86	
87	        this._shaderRefs.push(
88	          shader.uniforms as Record<string, { value: number | THREE.Vector3 }>,
89	        );
90	      };
