96	  private _syncFalloffConfig(): void {
97	    if (this._shaderRefs.length === 0) return;
98	    const falloff = this._resolveFalloffOptions();
99	    for (const uniforms of this._shaderRefs) {
100	      uniforms.uAboutFalloffInnerRadius.value = falloff.innerRadius;
101	      uniforms.uAboutFalloffOuterRadius.value = falloff.outerRadius;
102	      uniforms.uAboutFalloffBrightness.value = falloff.brightness;
103	      uniforms.uAboutFalloffDarkness.value = falloff.darkness;
104	      uniforms.uAboutFalloffBlendPower.value = falloff.blendPower;
105	    }
106	  }
