108	  private _syncFalloffCenter(): void {
109	    if (this._shaderRefs.length === 0) return;
110	    const astronaut = this._resolveAstronaut();
111	    if (!astronaut) return;
112	    const centerYOffset = this._resolveFalloffOptions().centerYOffset;
113	    astronaut.getWorldPosition(this._falloffCenter);
114	    this._falloffCenter.y += centerYOffset;
