117	  private _resolveAstronaut(): THREE.Object3D | null {
118	    if (this._astronaut && this._astronaut.parent) return this._astronaut;
119	    const astronaut =
120	      this._context?.scene?.getObjectByName(ABOUT_ASTRONAUT_ROOT_NAME) ?? null;
121	    if (!(astronaut instanceof THREE.Object3D)) return null;
