296	  private _applyGroupTransformsFromProxy(): void {
297	    for (const key of ["ground"] as const) {
298	      const group = this._groups[key];
299	      if (!group) continue;
300	      const src = this._timelineProxy[key];
301	      if (!src?.position || !src?.rotation || !src?.scale) continue;
302	      group.position.set(
303	        src.position.x ?? 0,
304	        src.position.y ?? 0,
305	        src.position.z ?? 0,
306	      );
