312	  private _applyProfileByProgress(): void {
313	    if (this._profileStops.length === 0) return;
314	    const sampled = this._sampleProfile(this._flightProgress);
315	    if (!sampled) return;
316	    const [left, right, t] = sampled;
317	
318	    const keys = new Set<string>([
319	      ...Object.keys(left.values),
320	      ...Object.keys(right.values),
321	    ]);
322	
323	    for (const key of keys) {
324	      if (key === "flightProgress" || key === "intensity") continue;
325	      const lv = left.values[key];
326	      const rv = right.values[key];
327	      if (!Number.isFinite(lv as number) && !Number.isFinite(rv as number)) {
328	        continue;
329	      }
330	      const l = Number.isFinite(lv as number) ? Number(lv) : Number(rv);
331	      const r = Number.isFinite(rv as number) ? Number(rv) : l;
332	      const value = l + (r - l) * t;
333	
334	      const light = this._lights.get(key);
335	      if (light) {
336	        light.intensity = value * this._masterIntensity;
337	      }
338	    }
339	  }
