471	  private _createDefaultGroupProxy(): GroupTransformProxy {
472	    return {
473	      position: { x: 0, y: 0, z: 0 },
474	      rotation: { x: 0, y: 0, z: 0 },
475	      scale: { x: 1, y: 1, z: 1 },
476	    };
477	  }
