16	export class SceneSheetEffectRuntime<
17	  TSceneKey extends string = string,
18	  TSheetId extends string = string,
19	> {
20	  private _previousSceneKey: TSceneKey | null = null;
21	  private _previousSheetId: TSheetId | null = null;
22	
23	  sync(
24	    scene: Scene | null,
25	    nextSceneKey: TSceneKey,
