30	      this._previousSheetId !== nextSheetId;
31	    if (!hasChanged) return;
32	
33	    const event: SceneSheetChangeEvent<TSceneKey, TSheetId> = {
34	      sceneKey: nextSceneKey,
35	      previousSceneKey: this._previousSceneKey,
36	      sheetId: nextSheetId,
37	      previousSheetId: this._previousSheetId,
38	    };
