28	function buildScatterPositions(
29	  totalCards: number,
30	  spreadX: number,
31	  spreadY: number,
32	): WorksScatterPosition[] {
33	  const cols = Math.ceil(Math.sqrt(totalCards * (spreadX / spreadY)));
34	  const rows = Math.ceil(totalCards / cols);
35	  const stepX = spreadX / Math.max(1, cols);
36	  const stepY = spreadY / Math.max(1, rows);
37	  const out: WorksScatterPosition[] = [];
38	  for (let row = 0; row < rows && out.length < totalCards; row += 1) {
39	    const rowOffset = (row % 2) * (stepX * 0.25);
40	    for (let col = 0; col < cols && out.length < totalCards; col += 1) {
41	      const x = (col - (cols - 1) / 2) * stepX + rowOffset;
42	      const y = (row - (rows - 1) / 2) * stepY;
43	      out.push({ x, y });
44	    }
45	  }
46	  return out;
47	}
