49	function sortScatterPositionsFromCenter(
50	  positions: ReadonlyArray<WorksScatterPosition>,
51	): WorksScatterPosition[] {
52	  return [...positions].sort((left, right) => {
53	    const distanceDelta =
54	      Math.hypot(left.x, left.y) - Math.hypot(right.x, right.y);
55	    if (distanceDelta !== 0) {
56	      return distanceDelta;
57	    }
58	    if (left.y !== right.y) {
59	      return left.y - right.y;
60	    }
61	    return left.x - right.x;
62	  });
63	}
