501	  update(delta: number): void {
502	    if (!this.camera || !this.scene) return;
503	    const camera = this.camera;
504	    this.cameraMotionRuntime.updateFrame(camera, delta);
505	    const positionFactor = 1 - Math.pow(1 - this.layout.positionLerp, delta * 60);
506	    const opacityFactor = 1 - Math.pow(1 - this.layout.opacityLerp, delta * 60);
507	    const scaleFactor = 1 - Math.pow(1 - this.layout.scaleLerp, delta * 60);
508	    const isGridView = this.viewMode === "grid";
509	    const hover =
510	      this.hovered && this.isMeshInCategory(this.hovered) ? this.hovered : null;
511	    const blendT =
512	      this._filterBlendStartMs > 0
513	        ? Math.min(
514	            1,
515	            (performance.now() - this._filterBlendStartMs) /
516	              WorksSceneManager._filterBlendMs,
517	          )
518	        : 1;
519	    const filterEase = 1 - Math.pow(1 - blendT, 3);
520	    for (let index = 0; index < this.meshes.length; index += 1) {
521	      const mesh = this.meshes[index];
522	      const target = this.targetPositions[index] ?? this.scatterPositions[index];
523	      const isActiveCategory = this.isMeshInCategory(mesh);
524	      const wasIn = this._meshIncludedInFilter(mesh, this._filterPrevCategory);
525	      const nowIn = isActiveCategory;
526	      let targetY = target.y;
527	      if (wasIn && !nowIn && blendT < 1) {
528	        targetY += (1 - filterEase) * 6.5;
529	      }
530	      if (!wasIn && nowIn && blendT < 1) {
531	        targetY -= (1 - filterEase) * 7.5;
532	      }
533	      mesh.position.x += (target.x - mesh.position.x) * positionFactor;
534	      mesh.position.y += (targetY - mesh.position.y) * positionFactor;
535	      mesh.position.z += (0 - mesh.position.z) * positionFactor;
536	      mesh.quaternion.copy(camera.quaternion);
537	      const opacityAnchor = isActiveCategory ? target : mesh.position;
538	      const distance = dist2d(
539	        camera.position.x,
540	        camera.position.y,
541	        opacityAnchor.x,
542	        opacityAnchor.y,
543	      );
544	      let targetOpacity = Math.max(0, Math.min(0.92, 1 - (distance - 8) * 0.025));
545	      if (!isActiveCategory) targetOpacity = 0;
546	      if (isActiveCategory && this.activeCategory !== null) {
547	        targetOpacity = Math.max(0.3, targetOpacity);
548	      }
549	      if (isGridView) targetOpacity = 0;

550	      if (hover) targetOpacity = hover === mesh ? 1 : targetOpacity * 0.55;
551	      if (nowIn && !wasIn) {
552	        targetOpacity *= filterEase;
553	      }
554	      const material = mesh.material as THREE.MeshBasicMaterial;
555	      material.opacity += (targetOpacity - material.opacity) * opacityFactor;
556	      const steadyScale = hover === mesh ? 1.06 : 1;
557	      mesh.scale.x += (steadyScale - mesh.scale.x) * scaleFactor;
558	      mesh.scale.y += (steadyScale - mesh.scale.y) * scaleFactor;
559	    }
560	  }
