799	  ): WorksScatterPosition {
800	    if (positions.length === 0) {
801	      return { x: 0, y: 0 };
802	    }
803	    let minX = positions[0]?.x ?? 0;
804	    let maxX = minX;
805	    let minY = positions[0]?.y ?? 0;
806	    let maxY = minY;
807	    for (let index = 1; index < positions.length; index += 1) {
808	      const position = positions[index];
809	      if (!position) continue;
810	      minX = Math.min(minX, position.x);
811	      maxX = Math.max(maxX, position.x);
812	      minY = Math.min(minY, position.y);
813	      maxY = Math.max(maxY, position.y);
814	    }
815	    return {
816	      x: (minX + maxX) * 0.5,
817	      y: (minY + maxY) * 0.5,
818	    };
